@Injectable()
export class EgapboardDetailsService {
  private readonly logger: AppLogger = new AppLogger(
    EgapboardDetailsService.name,
  );

  private readonly customHttpService: HttpService;

  public constructor(
    private readonly urlApiConfigService: UrlApiConfigService,
    private readonly apiManagerConfigService: ApiManagerConfigService,
    private readonly httpService: HttpService,
    private readonly redisService: RedisService,
  ) {
    const httpsAgent = new https.Agent({
      rejectUnauthorized: true, // Enforce SSL Certificate Verification
    });

    // Create a custom Axios instance using the custom HTTPS agent
    const axiosConfig: AxiosRequestConfig = {
      headers: this.httpService.axiosRef.defaults
        .headers as AxiosRequestConfig['headers'], // Use axios headers type
      httpsAgent,
    };

    const customAxiosInstance = axios.create(axiosConfig);

    // Initialize a new HttpService with the custom Axios instance
    this.customHttpService = new HttpService(customAxiosInstance);
  }

  // Alert-related methods
  public async getWorkcentersForResources(
    plant: number,
    resourceIds: Array<string>,
  ): Promise<Array<string>> {
    const { plantHryApiAppId } = this.urlApiConfigService;
    const daprClient = new DaprClient();
    try {
      const body = {
        plant,
        resourceIds,
      };

      const response = (await daprClient.invoker.invoke(
        plantHryApiAppId,
        'resource/getWorkcentersForResources',
        HttpMethod.POST,
        body,
      )) as GetWorkcentersForResourcesResponseDto;
      // Extract only workcenterId values, filtering out null values
      const workcenterIds = response.resources
        .map((resource) => resource.workcenterId)
        .filter((id): id is string => id !== null);

      return workcenterIds;
    } catch (error) {
      this.logger.error('Error getting workcenters for resources:', error);
      return [];
    }
  }

  public async getAlertCountsByWorkcenter(
    plant: number,
    workcenterIds: Array<string>,
  ): Promise<Array<AlertCountsByWorkcenterResponseDto>> {
    const { orderApiAppId } = this.urlApiConfigService;
    const daprClient = new DaprClient();
    try {
      const body = {
        plant,
        workcenterIds,
      };

      const response = (await daprClient.invoker.invoke(
        orderApiAppId,
        'alert/alert-counts-by-workcenter',
        HttpMethod.POST,
        body,
      )) as Array<AlertCountsByWorkcenterResponseDto>;

      return response;
    } catch (error) {
      this.logger.error('Error getting alert counts by workcenter:', error);
