          const wcDetails = workcenterDetails[alert.workcenter];
          return {
            ...alert,
            endPreparation:
              alert.endPreparation !== undefined &&
              alert.endPreparation !== null
                ? formatUtcDateInPlantTimezone(
                    new Date(alert.endPreparation),
                    timezone,
                  )
                : alert.endPreparation,
            newPromiseTime:
              alert.newPromiseTime !== undefined &&
              alert.newPromiseTime !== null
                ? formatUtcDateInPlantTimezone(
                    new Date(alert.newPromiseTime),
                    timezone,
                  )
                : alert.newPromiseTime,
