  // Detail methods
  public async getOkFirstPartDetails(
    plant: string,
    shiftStartDate: string,
    shiftEndDate: string,
    gapId: string,
    timezone: string,
  ): Promise<Array<OkFirstPartDetailItemDto>> {
    const apiManagerUrl = await this.apiManagerConfigService.apiManager();
    if (!this.apiManagerConfigService.apiManager) {
      this.logger.error('API Manager setup is incomplete');
      return [];
    }
    try {
      // Convert dates to ISO format
      const shiftStartUtcIso = resolveToUtcIso(shiftStartDate, timezone);
      const shiftEndUtcIso = resolveToUtcIso(shiftEndDate, timezone);

      // Build query parameters using DTO
      const queryDto = new OkFirstPartQueryDto(
        gapId,
        shiftStartUtcIso,
        shiftEndUtcIso,
      );
      const queryParameters = new URLSearchParams(
        queryDto.toQueryParams(),
      ).toString();

      const mLeanUrl = `${apiManagerUrl}/mlean/api/v1/ok-first-part-schedules?${queryParameters}`;

      const { mainSecretStore } = this.apiManagerConfigService;
      const apiMgrKeySecretName = this.apiManagerConfigService.apiMgrSecretName;
      const daprClient = new DaprClient();
      const apiMgrKeyObject = await daprClient.secret.get(
        mainSecretStore,
        apiMgrKeySecretName,
      );
      const apiMgrKeyValue = Object.values(apiMgrKeyObject)[0];

      // Get mLean token from Redis cache
      const mleanToken = await getMLeanTokenFromCache(this.redisService, plant);
      if (!mleanToken) {
        this.logger.error(
          'Failed to obtain mLean token on getOkFirstPartDetails',
        );
        return [];
      }

      const headersDto = new MleanApiHeadersDto(
        apiMgrKeyValue,
        plant,
        mleanToken,
      );

      const responseApiMgr = await firstValueFrom(
        this.customHttpService.get(mLeanUrl, {
          headers: headersDto,
        }),
      );

      const responseData = responseApiMgr.data as {
        count: number;
        results: Array<OkFirstPartScheduleItemApiDto>;
      };

      // Check if responseData is valid
      if (
        !Array.isArray(responseData.results) ||
        responseData.results.length === 0
      ) {
        return [];
      }

      // Fetch patterns to find the LINE pattern ID
      const patternsUrl = `${apiManagerUrl}/mlean/api/v1/patterns`;
      const patternsResponse = await firstValueFrom(
        this.customHttpService.get(patternsUrl, {
          headers: headersDto,
        }),
      );
      // Assuming the patterns API returns an array of patterns with id and localized name
      const patternsData = patternsResponse.data as Array<{
        id: number;
        localized?: {
          en?: string;
        };
      }>;

      // Find the pattern with localized name "LINE" (case-insensitive)
      const linePattern = patternsData.find(
        (pattern) => pattern?.localized?.en?.trim().toUpperCase() === 'LINE',
      );
      if (!linePattern?.id) {
        this.logger.warn(
          `LINE pattern not found in /patterns response for plant ${plant}`,
        );
        return [];
      }

      // Transform each item and fetch perimeter details
      const detailsPromises = responseData.results.map(async (item) => {
        // Fetch perimeter description from the second API
        let subPerimeterDescription = '';
        try {
          const perimeterUrl = `${apiManagerUrl}/mlean/api/v1/perimeters/?format=info&pattern=${linePattern.id}&parent=${gapId}&id=${item.perimeter}`;
          const perimeterResponse = await firstValueFrom(
            this.customHttpService.get(perimeterUrl, {
              headers: headersDto,
            }),
          );

          const perimeterData =
            perimeterResponse.data as Array<PerimeterApiResponseDto>;
          if (Array.isArray(perimeterData) && perimeterData.length > 0) {
            subPerimeterDescription = perimeterData[0].name || '';
          }
        } catch (error) {
          this.logger.error(
            `Error fetching perimeter details for perimeter ${item.perimeter}:`,
            error,
          );
          subPerimeterDescription = '';
        }

        // Timezone-safe duration calc: use UTC epoch math only
        const createdMs = Date.parse(item.created);
        const closedMs = item.closed_date
          ? Date.parse(item.closed_date)
          : Date.now();

        const safeCreatedMs = Number.isFinite(createdMs)
          ? createdMs
          : Date.now();
        const safeClosedMs = Number.isFinite(closedMs) ? closedMs : Date.now();

        const durationMs = Math.max(0, safeClosedMs - safeCreatedMs);
        const totalSeconds = Math.floor(durationMs / 1000);
        const hours = Math.floor(totalSeconds / 3600);
        const minutes = Math.floor((totalSeconds % 3600) / 60);
        const seconds = totalSeconds % 60;
        const duration = `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;

        // Convert dates to plant timezone and format as yyyy-mm-dd HH:mm:ss
        const createdDateUtc = new Date(item.created);
        const creationDate =
          formatUtcDateInPlantTimezone(createdDateUtc, timezone) ||
          item.created;

        let closedDate: string | null = null;
        if (item.closed_date) {
          const closedDateUtc = new Date(item.closed_date);
          closedDate =
            formatUtcDateInPlantTimezone(closedDateUtc, timezone) ||
            item.closed_date;
        }

        // Determine color based on status and closed_date
        // Closed with status 0 → Green, all other cases → Red
        const color: 'green' | 'red' =
          item.closed_date && item.status === 0 ? 'green' : 'red';

        return new OkFirstPartDetailItemDto(
          item.id,
          creationDate,
          closedDate,
          duration,
          item.perimeter,
          subPerimeterDescription,
          color,
        );
      });

      const details = await Promise.all(detailsPromises);
      return details;
    } catch (error) {
      this.logger.error('Error fetching OK First Part Details:', error);
      return [];
    }
  }

