        plant,
        mleanToken,
      );

      const responseApiMgr = await firstValueFrom(
        this.customHttpService.get(mLeanUrl, {
          headers: headersDto,
        }),
      );

      // API returns an array directly
      const responseData = responseApiMgr.data as Array<RoutineApiResponseDto>;

      // Check if responseData is an array
      if (!Array.isArray(responseData) || responseData.length === 0) {
        return [];
      }

      // Transform each item: map status to color and rename name to description
      const routineDetails = responseData.map((item) => {
        let color: 'green' | 'red' | 'grey';
        let status: 'OK' | 'NOK' | 'NA';

        // Status = 'OK' or 'N/A' → Green
        // Status = 'NOK' or NULL or any other value → Red
        if (item.status === 'OK') {
          color = 'green';
          status = 'OK';
        } else if (item.status === 'N/A' || item.status === null) {
          color = 'grey';
          status = 'NA';
        } else {
          color = 'red';
          status = 'NOK';
        }

        return new RoutineDetailItemDto(
          item.schedule_entry_id,
          item.schedule_id,
          item.name,
          status,
          color,
        );
      });

      return routineDetails;
    } catch (error) {
      this.logger.error('Error fetching Routine Details:', error);
      return [];
    }
  }

