        apiMgrKeyValue,
        plant,
        mleanToken,
      );

      const responseApiMgr = await firstValueFrom(
        this.customHttpService.get(mLeanUrl, {
          headers: headersDto,
        }),
      );

      // API returns an array of checkpoints
      const responseData =
        responseApiMgr.data as Array<GembaWalkCheckpointApiResponseDto>;
      // Transform each checkpoint
      const transformedData = responseData.map((checkpoint) => {
        // Transform checkpoint_results: convert status to color
        const transformedResults = checkpoint.checkpoint_results.map(
          (result) => {
            const statusColor: 'green' | 'red' =
              result.status === 1 ? 'green' : 'red'; // Status OK = green, otherwise red (Not assessed considered as NOK+ Status NOK)

            return new CheckpointResultDto(result.label, statusColor);
          },
        );

        // Determine labelIsDashorOK: true if any label is "-" or "OK"
        const labelIsDashorOK = checkpoint.checkpoint_results.some(
          (result) => result.label === '-' || result.label === 'OK',
        );

        return new ManagementControlDetailsResponseDto(
          checkpoint.id,
          checkpoint.checkpoint_description,
          labelIsDashorOK,
          transformedResults,
          checkpoint.checkpoint_category_color,
          checkpoint.checkpoint_category_description,
        );
      });

      return transformedData;
    } catch (error) {
      this.logger.error('Error fetching Management Control Details:', error);
      return [];
