@Injectable()
export class EgapboardService {
  private readonly logger: AppLogger = new AppLogger(EgapboardService.name);

  private readonly customHttpService: HttpService;

  public constructor(
    private readonly urlApiConfigService: UrlApiConfigService,
    private readonly apiManagerConfigService: ApiManagerConfigService,
    private readonly httpService: HttpService,
    private readonly redisService: RedisService,
    private readonly egapboardDetailsService: EgapboardDetailsService,
    private readonly epartboardService: EpartboardService,
  ) {
    const httpsAgent = new https.Agent({
      rejectUnauthorized: true, // Enforce SSL Certificate Verification
    });

    // Create a custom Axios instance using the custom HTTPS agent
    const axiosConfig: AxiosRequestConfig = {
      headers: this.httpService.axiosRef.defaults
        .headers as AxiosRequestConfig['headers'], // Use axios headers type
      httpsAgent,
    };

    const customAxiosInstance = axios.create(axiosConfig);

    // Initialize a new HttpService with the custom Axios instance
    this.customHttpService = new HttpService(customAxiosInstance);
  }

  public async getMLeanToken(
    plant: string,
  ): Promise<MleanTokenCache | undefined> {
    const apiManagerUrl = await this.apiManagerConfigService.apiManager();
    if (!this.apiManagerConfigService.apiManager) {
      throw new Error('API Manager setup is incomplete');
    }
    const daprClient = new DaprClient();
    const mLeanUrl = `${apiManagerUrl}/mlean/api/v1/login/`;
    const { mainSecretStore } = this.apiManagerConfigService;
    const username = await this.apiManagerConfigService.mleanUsername();
    const { mleanPasswordSecretName } = this.apiManagerConfigService;
    const mleanPasswordObject = await daprClient.secret.get(
      mainSecretStore,
      mleanPasswordSecretName,
    );
    const password = Object.values(mleanPasswordObject)[0];
    const apiMgrKeySecretName = this.apiManagerConfigService.apiMgrSecretName;
    const apiMgrKeyObject = await daprClient.secret.get(
      mainSecretStore,
      apiMgrKeySecretName,
    );
    const apiMgrKeyValue = Object.values(apiMgrKeyObject)[0];

    if (!username || !password || !apiMgrKeyValue) {
      this.logger.error(
        'Missing required environment variables for mLean login',
      );
      return undefined;
    }

    const payload = {
      password,
      username,
    };
    try {
      const headersDto = new MleanApiHeadersDto(apiMgrKeyValue, plant);
      const response = await firstValueFrom(
        this.customHttpService.post(mLeanUrl, payload, {
          headers: headersDto,
        }),
      );
      const token = response.data?.token;
      if (!token) {
        this.logger.error('No token received from mLean login response');
        return undefined;
      }

      // Decode JWT token to get payload
      const decoded = jwt.decode(token) as JwtDecodedDto;

      if (!decoded) {
        this.logger.error('Failed to decode JWT token');
        return undefined;
      }

      // Map JWT payload to MleanTokenCache interface
      const tokenCache: MleanTokenCache = {
        exp: decoded.exp,
        iss: decoded.iss,
        lt: decoded.lt,
        nbf: decoded.nbf,
        scope: decoded.scope,
        token,
        userId: decoded.user_id,
      };

      // Store token in Redis with plant as key
      await this.redisService.write(plant, tokenCache);

      return tokenCache;
    } catch (error) {
      this.logger.error('Error during mLean login:', error);
      return undefined;
    }
  }

  public async assignGapToResources(
