  public async getGapMleanList(
    plant: string,
  ): Promise<Array<Record<string, unknown>>> {
    const apiManagerUrl = await this.apiManagerConfigService.apiManager();
    if (!this.apiManagerConfigService.apiManager) {
      this.logger.error('API Manager setup is incomplete');
      return [];
    }
    try {
      const { mainSecretStore } = this.apiManagerConfigService;
      const apiMgrKeySecretName = this.apiManagerConfigService.apiMgrSecretName;
      const daprClient = new DaprClient();
      const apiMgrKeyObject = await daprClient.secret.get(
        mainSecretStore,
        apiMgrKeySecretName,
      );
      const apiMgrKeyValue = Object.values(apiMgrKeyObject)[0];

      // Get mLean token from Redis cache
      let mleanToken = await getMLeanTokenFromCache(this.redisService, plant);

      // If token not in cache or expired/expiring soon (within 10 minutes), fetch new token
      if (!mleanToken) {
        await ensureTokenIsCached(
          this.redisService,
          plant,
          this.getMLeanToken.bind(this),
        );
        mleanToken = await getMLeanTokenFromCache(this.redisService, plant);
      }

      const headersDto = new MleanApiHeadersDto(
        apiMgrKeyValue,
        plant,
        mleanToken,
      );

      const patternsUrl = `${apiManagerUrl}/mlean/api/v1/patterns`;
      const patternsResponse = await firstValueFrom(
        this.customHttpService.get(patternsUrl, {
          headers: headersDto,
        }),
      );

      const patternsData = patternsResponse.data as Array<{
        id: number;
        localized?: {
          en?: string;
        };
      }>;

      const gapPattern = patternsData.find(
        (pattern) => pattern?.localized?.en?.trim().toUpperCase() === 'GAP',
      );
      if (!gapPattern?.id) {
        this.logger.warn(
          `GAP pattern not found in /patterns response for plant ${plant}`,
        );
        return [];
      }

      const queryParameters = new URLSearchParams({
        format: 'info',
        pattern: String(gapPattern.id),
      }).toString();

      const mLeanUrl = `${apiManagerUrl}/mlean/api/v1/perimeters/?${queryParameters}`;

      const responseApiMgr = await firstValueFrom(
        this.customHttpService.get(mLeanUrl, {
          headers: headersDto,
        }),
      );

      const allData = responseApiMgr.data as Array<Record<string, unknown>>;
      return Array.isArray(allData) ? allData : [];
    } catch (error) {
      this.logger.error(
        `Error fetching M-LEAN gap list for plant ${plant}:`,
        error,
      );
      throw error;
    }
  }

  public async getOkFirstPart(
    plant: string,
    shiftStartDate: string,
    shiftEndDate: string,
    gapId: string,
    timezone: string,
    token?: string,
  ): Promise<OkFirstPartResponseDto | undefined> {
    const apiManagerUrl = await this.apiManagerConfigService.apiManager();
    if (!this.apiManagerConfigService.apiManager) {
      this.logger.error('API Manager setup is incomplete');
      return new OkFirstPartResponseDto(0, 0);
    }
    try {
      // Convert dates to  ISO format
      const shiftStartUtcIso = resolveToUtcIso(shiftStartDate, timezone);
      const shiftEndUtcIso = resolveToUtcIso(shiftEndDate, timezone);

      // Build query parameters using DTO
      const queryDto = new OkFirstPartQueryDto(
        gapId,
        shiftStartUtcIso,
        shiftEndUtcIso,
      );
      const queryParameters = new URLSearchParams(
        queryDto.toQueryParams(),
      ).toString();

      const mLeanUrl = `${apiManagerUrl}/mlean/api/v1/ok-first-part-schedules?${queryParameters}`;

      const { mainSecretStore } = this.apiManagerConfigService;
      const apiMgrKeySecretName = this.apiManagerConfigService.apiMgrSecretName;
      const daprClient = new DaprClient();
      const apiMgrKeyObject = await daprClient.secret.get(
        mainSecretStore,
        apiMgrKeySecretName,
      );
      const apiMgrKeyValue = Object.values(apiMgrKeyObject)[0];

      // Use provided token
      const mleanToken = token;

      const headersDto = new MleanApiHeadersDto(
        apiMgrKeyValue,
        plant,
        mleanToken,
      );

      const responseApiMgr = await firstValueFrom(
        this.customHttpService.get(mLeanUrl, {
          headers: headersDto,
        }),
      );

      const responseData = responseApiMgr.data as {
        count: number;
        results: Array<{ status: number }>;
      };

      // Count records with status = 0
      const okCount = responseData.results.filter(
        (record) => record.status === 0,
      ).length;
      const totalCount = responseData.count;

      return new OkFirstPartResponseDto(okCount, totalCount);
    } catch (error) {
      this.logger.error('Error fetching OK First Part schedules:', error);
      return undefined;
    }
  }

