  public async getRoutines(
    plant: string,
    shiftStartDate: string,
    shiftEndDate: string,
    teamId: string,
    timezone: string,
    token?: string,
  ): Promise<RoutinesResponseDto | undefined> {
    // Check if teamId exists
    if (!teamId || teamId.trim() === '') {
      this.logger.warn('TeamId parameter is missing or empty');
      return undefined;
    }

    const apiManagerUrl = await this.apiManagerConfigService.apiManager();
    if (!this.apiManagerConfigService.apiManager) {
      this.logger.error('API Manager setup is incomplete');
      return undefined;
    }
    try {
      // Convert dates to ISO format
      const shiftStartUtcIso = resolveToUtcIso(shiftStartDate, timezone);
      const shiftEndUtcIso = resolveToUtcIso(shiftEndDate, timezone);

      // Build query parameters using DTO
      const queryDto = new RoutinesQueryDto(
        teamId,
        shiftStartUtcIso,
        shiftEndUtcIso,
      );
      const queryParameters = new URLSearchParams(
        queryDto.toQueryParams(),
      ).toString();

      const mLeanUrl = `${apiManagerUrl}/mlean/api/v1/daily-round-assessments-for-board?${queryParameters}`;

      const { mainSecretStore } = this.apiManagerConfigService;
      const apiMgrKeySecretName = this.apiManagerConfigService.apiMgrSecretName;
      const daprClient = new DaprClient();
      const apiMgrKeyObject = await daprClient.secret.get(
        mainSecretStore,
        apiMgrKeySecretName,
      );
      const apiMgrKeyValue = Object.values(apiMgrKeyObject)[0];

      // Use provided token
      const mleanToken = token;

      if (!mleanToken) {
        this.logger.error('Failed to obtain mLean token on getRoutines');
        return undefined;
      }

      const headersDto = new MleanApiHeadersDto(
        apiMgrKeyValue,
        plant,
        mleanToken,
      );

      const responseApiMgr = await firstValueFrom(
        this.customHttpService.get(mLeanUrl, {
          headers: headersDto,
        }),
      );

      // API returns an array directly, not wrapped in results
      const responseData = responseApiMgr.data as Array<
        Record<string, unknown>
      >;

      // Check if responseData is an array
      if (!Array.isArray(responseData)) {
        this.logger.warn('Response data is not an array');
        return undefined;
      }

      // Count done routines (status = 'OK')
      const doneCount = responseData.filter(
        (record) => record.status === 'OK',
      ).length;

      // Total count based on schedule_entry_id
      const totalCount = responseData.length;

      return new RoutinesResponseDto(doneCount, totalCount);
    } catch (error) {
      this.logger.error('Error fetching routines:', error);
      return undefined;
    }
  }

