      const responseData = responseApiMgr.data as Array<{ result: number }>;
      // Check if responseData is an array
      if (!Array.isArray(responseData) || responseData.length === 0) {
        return new TpmResponseDto(0, 0, true);
      }

      // Count TpmOk: items where result ≠ -2
      const tpmOkCount = responseData.filter(
        (record) => record.result === 1,
      ).length;

      const totalCount = responseData.length;

      return new TpmResponseDto(tpmOkCount, totalCount, false);
    } catch (error) {
      this.logger.error('Error fetching TPM:', error);
      return new TpmResponseDto(0, 0, true);
    }
  }

