  public async getAllKpis(
    plant: string,
    shiftStartDate: string,
    shiftEndDate: string,
    gapId: string,
    timezone: string,
    teamId?: string,
    currentShiftHourNumber?: string,
  ): Promise<AllKpisResponseDto> {
    // Get mLean token from Redis cache

    let mleanToken = await getMLeanTokenFromCache(this.redisService, plant);

    // If token not in cache or expired/expiring soon (within 10 minutes), fetch new token
    if (!mleanToken) {
      await ensureTokenIsCached(
        this.redisService,
        plant,
        this.getMLeanToken.bind(this),
      );
      mleanToken = await getMLeanTokenFromCache(this.redisService, plant);
    }

    // Call all KPI functions in parallel with the shared token
    const [
      okFirstPartResult,
      routinesResult,
      tpmResult,
      managementControlResult,
    ] = await Promise.all([
      this.getOkFirstPart(
        plant,
        shiftStartDate,
        shiftEndDate,
        gapId,
        timezone,
        mleanToken,
      ),
      teamId
        ? this.getRoutines(
            plant,
            shiftStartDate,
            shiftEndDate,
            teamId,
            timezone,
            mleanToken,
          )
        : Promise.resolve(null),
      this.getTpm(
        plant,
        shiftStartDate,
        shiftEndDate,
        gapId,
        timezone,
        mleanToken,
      ),
      teamId
        ? this.getManagementControl(
            plant,
            shiftStartDate,
            shiftEndDate,
            teamId,
            timezone,
            mleanToken,
            currentShiftHourNumber,
          )
        : Promise.resolve(null),
    ]);

    return new AllKpisResponseDto(
      okFirstPartResult?.okFirstPart,
      routinesResult?.routines,
      tpmResult?.tpm,
      managementControlResult?.managementControl,
    );
  }

