  public async getManagementControl(
    plant: string,
    shiftStartDate: string,
    shiftEndDate: string,
    team: string,
    timezone: string,
    token?: string,
    currentShiftHourNumber?: string,
  ): Promise<ManagementControlResponseDto | undefined> {
    // Check if team exists
    if (!team || team.trim() === '') {
      this.logger.warn('Team parameter is missing or empty');
      return undefined;
    }

    const apiManagerUrl = await this.apiManagerConfigService.apiManager();
    if (!this.apiManagerConfigService.apiManager) {
      this.logger.error('API Manager setup is incomplete');
      return undefined;
    }
    try {
      // Convert dates to ISO format
      const shiftStartUtcIso = resolveToUtcIso(shiftStartDate, timezone);
      const shiftEndUtcIso = resolveToUtcIso(shiftEndDate, timezone);

      // Build query parameters using DTO
      const queryDto = new ManagementControlQueryDto();
      queryDto.team = team;
      queryDto.shiftStartDate = shiftStartUtcIso;
      queryDto.shiftEndDate = shiftEndUtcIso;

      const queryParameters = new URLSearchParams(
        queryDto.toQueryParams(),
      ).toString();

      const mLeanUrl = `${apiManagerUrl}/mlean/api/v1/gemba-walk-checkpoints-for-board?${queryParameters}`;

      const { mainSecretStore } = this.apiManagerConfigService;
      const apiMgrKeySecretName = this.apiManagerConfigService.apiMgrSecretName;
      const daprClient = new DaprClient();
      const apiMgrKeyObject = await daprClient.secret.get(
        mainSecretStore,
        apiMgrKeySecretName,
      );
      const apiMgrKeyValue = Object.values(apiMgrKeyObject)[0];
      // Use provided token
      const mleanToken = token;

      if (!mleanToken) {
        this.logger.error(
          'Failed to obtain mLean token on getManagementControl',
        );
        return undefined;
      }

      const headersDto = new MleanApiHeadersDto(
        apiMgrKeyValue,
        plant,
        mleanToken,
      );

      const responseApiMgr = await firstValueFrom(
        this.customHttpService.get(mLeanUrl, {
          headers: headersDto,
        }),
      );

      // API returns an array directly
      const responseData =
        responseApiMgr.data as Array<GembaWalkCheckpointApiResponseDto>;

      // Check if responseData is an array
      if (!Array.isArray(responseData) || responseData.length === 0) {
        this.logger.warn('Response data is not an array or is empty');
        return undefined;
      }

      // Helper function to get the matching checkpoint result based on currentShiftHourNumber or special labels
      const getMatchingCheckpointResult = (
        checkpointResults: Array<{ label: string; status: number | null }>,
      ): { label: string; status: number | null } | null => {
        if (!checkpointResults || checkpointResults.length === 0) {
          return null;
        }

        // First, try to find a match with currentShiftHourNumber if provided
        if (currentShiftHourNumber) {
          const matchingResult = checkpointResults.find(
            (result) => result.label === currentShiftHourNumber,
          );
          if (matchingResult) {
            return matchingResult;
          }
        }

        // If no match with currentShiftHourNumber, look for "OK" or "-"
        const specialLabel = checkpointResults.find(
          (result) => result.label === 'OK' || result.label === '-',
        );
        if (specialLabel) {
          return specialLabel;
        }

        return null;
      };

      // Get items with their matching checkpoint result
      const itemsWithMatchedResult = responseData
        .map((item) => ({
          item,
          matchedResult: getMatchingCheckpointResult(item.checkpoint_results),
        }))
        .filter((entry) => entry.matchedResult !== null);

      // Calculate numberOfItems: total count of all checkpoint items
      const numberOfItems = responseData.length;

      // Calculate controlAssessed: from those items, count where matched result status is 1, 0, -2, OR label is "OK"
      const controlAssessed = itemsWithMatchedResult.filter((entry) => {
        const matchedLabel = entry.matchedResult?.label;
        const matchedStatus = entry.matchedResult?.status;

        if (!matchedLabel) {
          return false;
        }

        // Check if it should be counted as assessed
        return (
          matchedStatus === 1 ||
          matchedStatus === 0 ||
          matchedStatus === -2 ||
          matchedLabel === 'OK'
        );
      }).length;

      return new ManagementControlResponseDto(controlAssessed, numberOfItems);
    } catch (error) {
      this.logger.error('Error fetching Management Control:', error);
      return undefined;
    }
  }

