  public async getXResourcesKpis(
    plant: string,
    gapId: string,
    shiftStartDate: string,
    shiftEndDate: string,
    timezone: string,
  ): Promise<ResourceKpisResponseDto> {
    // 1. Fetch all resources linked to the GAP
    const resources = await this.getResourcesByGapId(Number(plant), gapId);

    if (!resources || resources.length === 0) {
      return new ResourceKpisResponseDto([]);
    }

    // 2. For each resource, load hourly KPIs and scrap count
    const resourceKpis = await Promise.all(
      resources.map(async (resource) => {
        const hourlyQuery: HourlyAggregationQueryDto = {
          plant,
          resourceId: resource.resourceId,
          shiftEndDate,
          shiftStartDate,
          timezone,
        };

        const [hourlyData, scrapResult] = await Promise.all([
          this.epartboardService.getHourlyAggregation(hourlyQuery),
          this.epartboardService.getScrapCount(
            plant,
            resource.resourceId,
            shiftStartDate,
            shiftEndDate,
          ),
        ]);

        // 3. Aggregate shift totals from hourly data
        let totalTarget = 0;
        let totalProduction = 0;
        let totalDelta = 0;

        for (const hour of hourlyData) {
          totalTarget += Number(hour.target) || 0;
          totalProduction += Number(hour.production) || 0;
          totalDelta += Number(hour.delta) || 0;
        }

        const shiftTotals = new ResourceShiftTotalsDto(
          totalTarget,
          totalProduction,
          totalDelta,
          scrapResult.count,
        );

        // 4. Build hourly status timeline string
        const totalStatus = hourlyData
          .map((hour) =>
            typeof hour.status === 'string'
              ? hour.status
              : String(hour.status ?? ''),
          )
          .join(';');

        return new ResourceKpiItemDto(
          resource.resourceId,
          resource.resourceName,
          shiftTotals,
          totalStatus,
        );
      }),
    );

    return new ResourceKpisResponseDto(resourceKpis);
  }
}

type RawRecord = Record<string, unknown>;

interface ComplianceCell {
  isPolyvalent: boolean;
  levelId: number | undefined;
  levelValue: string | undefined;
  operatorId: number | undefined;
}

export const formatPolyvalenceTableData = (
  payload: RawRecord,
): Record<string, unknown> => {
  const rawWorkstations = Array.isArray(payload.workstations)
    ? (payload.workstations as Array<RawRecord>)
    : [];
  const rawOperators = Array.isArray(payload.operators)
    ? (payload.operators as Array<RawRecord>)
    : [];
  const compliancesMatrix = Array.isArray(payload.compliances)
    ? (payload.compliances as Array<unknown>)
    : [];

  const complianceByKey = new Map<string, RawRecord>();
  for (const row of compliancesMatrix) {
    if (Array.isArray(row)) {
      for (const cell of row) {
        if (cell && typeof cell === 'object') {
          const compliance = cell as RawRecord;
          const perimeterId = compliance['perimeter_id'];
          const operatorId = compliance['operator_id'];

          complianceByKey.set(`${perimeterId}:${operatorId}`, compliance);
        }
      }
    }
  }

  const operators = rawOperators.map((operator) => ({
    isNotOperator:
      typeof operator['is_not_operator'] === 'boolean'
        ? operator['is_not_operator']
        : false,
    operatorId:
      typeof operator['operator_id'] === 'number'
        ? operator['operator_id']
        : undefined,
    operatorIsStandardTrainer:
      typeof operator['operator_is_standard_trainer'] === 'boolean'
        ? operator['operator_is_standard_trainer']
        : false,
    operatorName:
      typeof operator['operator_name'] === 'string'
        ? operator['operator_name']
        : undefined,
    operatorRole:
      typeof operator['operator_role'] === 'string'
        ? operator['operator_role']
        : undefined,
    operatorRoleId:
      typeof operator['operator_role_id'] === 'number'
        ? operator['operator_role_id']
        : undefined,
  }));

  const rows = rawWorkstations.map((workstation) => {
    const workstationId =
      typeof workstation['perimeter_id'] === 'number'
        ? workstation['perimeter_id']
        : undefined;

    const cells: Array<ComplianceCell> = operators.map((operator) => {
      const { operatorId } = operator;
      if (typeof workstationId !== 'number' || typeof operatorId !== 'number') {
        return {
          isPolyvalent: false,
          levelId: undefined,
          levelValue: undefined,
          operatorId,
        };
      }

      const compliance = complianceByKey.get(`${workstationId}:${operatorId}`);
      return {
        isPolyvalent:
          typeof compliance?.['is_polyvalent'] === 'boolean'
            ? compliance['is_polyvalent']
            : false,
        levelId:
          typeof compliance?.['level_id'] === 'number'
            ? compliance['level_id']
            : undefined,
        levelValue:
          typeof compliance?.['level_value'] === 'string'
            ? compliance['level_value']
            : undefined,
        operatorId,
      };
    });

    return {
      cells,
      workstationId,
      workstationName:
        typeof workstation['perimeter_name'] === 'string'
          ? workstation['perimeter_name']
          : undefined,
    };
  });

  return {
    columns: operators,
    compliancesSummary: Array.isArray(payload['compliances_summary'])
      ? payload['compliances_summary']
      : [],
    globalCertificationState: payload['global_certification_state'],
    rows,
  };
};

