@Controller('epart-board')
@UseFilters(MesGenericErrorFilter)
@ApiTags('epart-board')
export class EpartboardController {
  public constructor(private readonly epartboardService: EpartboardService) {}

  @Get('getHierarchy/:userId')
  public async getRestrictedHierarchy(
    @Param('userId') userId: string,
  ): Promise<Array<PlanHierarchy> | undefined> {
    const result = await this.epartboardService.getHierarchy(userId);
    return result ?? [];
  }

  @Get('shift-context')
  public async getShiftContext(
    @Query() query: GetShiftContextDto,
  ): Promise<ShiftContextResult> {
    const result = await this.epartboardService.getShiftContext(query);
    return result;
  }

  @Get('hourly-aggregation')
  public async getHourlyAggregation(
    @Query() query: HourlyAggregationQueryDto,
  ): Promise<Array<HourlyAggregatedProductionDto>> {
    const result = await this.epartboardService.getHourlyAggregation(query);
    return result;
  }

  @Get('event-center/sd-comments')
  @ApiOperation({
    description:
      'Returns Event Center SD comment rows for the provided plant/resource and shift window. Missing hours are returned as NO_DATA rows.',
    summary: 'Get Event Center SD comments by shift window',
  })
  @eventCenterHourlyQueryDocumentation()
  @ApiOkResponse({
    description:
      'Event Center SD comments for each hour in the selected shift range.',
    isArray: true,
    type: EventCenterSdCommentDto,
  })
  @ApiBadRequestResponse({
    description: 'Request query validation failed.',
    type: ValidationErrorResponseDto,
  })
  @ApiInternalServerErrorResponse({
    description: 'Unexpected server-side failure while fetching SD comments.',
    type: InternalServerErrorResponseDto,
  })
  public async getEventCenterSdComments(
    @Query() query: HourlyAggregationQueryDto,
  ): Promise<Array<EventCenterSdCommentDto>> {
    const result = await this.epartboardService.getEventCenterSdComments(query);
    return result;
  }

  @Get('event-center/configuration-history')
  @ApiOperation({
    description:
      'Returns Event Center configuration timeline segments for the provided plant/resource and shift window.',
    summary: 'Get Event Center configuration history by shift window',
  })
