  @ApiOkResponse({
    description:
      'Configuration timeline segments grouped by shift hour. Hours without configuration segments return an empty items array.',
    isArray: true,
    type: EventCenterConfigurationHistoryDto,
  })
  @ApiBadRequestResponse({
    description: 'Request query validation failed.',
    type: ValidationErrorResponseDto,
  })
