  @Post('writeBackDescription')
  public async writeBackDescription(
    @Query() query: WriteBackActionDto,
  ): Promise<{ success: boolean }> {
    try {
      await this.epartboardService.insertSlowDown(query);
      return { success: true };
    } catch (error) {
      console.error('Error in writeBackTicket:', error);
      throw new HttpException(
        'Internal server error while writing back to MII',
        HttpStatus.INTERNAL_SERVER_ERROR,
      );
    }
