  @Post('balancing/configure')
  @ApiOperation({
    description:
      'Writes balancing changes for the selected resource and time interval. The request body contains the selected mode, target, operator count, and the start/end timestamps that define the balancing interval.',
    summary: 'Configure balancing for a resource',
  })
  @ApiBody({
    description:
      'Configuration payload to be written back. All date-time values must use MM/DD/YYYY HH:mm:ss format.',
    type: ConfigureBalancingDto,
  })
  @ApiOkResponse({
    description: 'Configuration was written successfully.',
    type: ConfigureBalancingResponseDto,
  })
  @ApiBadRequestResponse({
    description:
      'Request body validation failed or the supplied date range is invalid.',
    type: ValidationErrorResponseDto,
  })
  @ApiInternalServerErrorResponse({
    description:
      'Unexpected server-side failure while writing Configuration to downstream systems.',
    type: InternalServerErrorResponseDto,
  })
  public async configureBalancing(
    @Body() body: ConfigureBalancingDto,
  ): Promise<ConfigureBalancingResponseDto> {
    return this.epartboardService.configureBalancing({
      endDateTime: body.endDateTime,
      mode: body.mode,
      operatorCount: body.operatorCount,
