  /**
   * Configure balancing for a plant and resource.
   * @param parameters The configuration parameters.
   * @returns The configure balancing response.
   */
  public async configureBalancing(
    parameters: ConfigureBalancingParameters,
  ): Promise<ConfigureBalancingResponseDto> {
    const start = DateTime.fromFormat(
      parameters.startDateTime,
      'MM/dd/yyyy HH:mm:ss',
    );
    const end = DateTime.fromFormat(
      parameters.endDateTime,
      'MM/dd/yyyy HH:mm:ss',
    );
    const writeDateTime = DateTime.fromFormat(
      parameters.writeDateTime,
      'MM/dd/yyyy HH:mm:ss',
    );

    if (!start.isValid || !end.isValid || !writeDateTime.isValid) {
      throw new Error('Invalid startDateTime/endDateTime/writeDateTime format');
    }
    if (end <= start) {
      throw new Error('endDateTime must be after startDateTime');
    }
    const validation = await this.validateBalancingRange({
      endDateTime: parameters.endDateTime,
      plant: parameters.plant,
      resourceId: parameters.resourceId,
      startDateTime: parameters.startDateTime,
      timezone: parameters.timezone,
    });

    if (!validation.valid) {
      throw new BadRequestException(
        validation.message ?? 'Selected Configuration range is invalid.',
      );
    }

    // 1. Insert MODE record (ACTION = mode, TARGET = chosen target, every time)
    const modeResult = await this.insertEDashboardAction(
      parameters.plant,
      parameters.resourceId,
      parameters.mode,
      '',
      parameters.operatorCount,
      parameters.startDateTime,
      parameters.endDateTime,
      parameters.target,
    );

    if (!modeResult.success) {
      throw new BadRequestException(
        modeResult.message ?? 'Balancing mode writeback to MII failed',
      );
    }
    return { success: true };
  }

  /**
   * Insert an eDashboard action for a plant and resource.
   * @param parameters The parameters.
   * @returns The result of the action insertion.
   */
  public async insertSlowDown(
    parameters: WriteBackActionDto,
  ): Promise<{ success: boolean } | undefined> {
    const apiManagerUrl = await this.apiManagerConfigService.apiManager();
    const mesUserName = await this.apiManagerConfigService.mesUserName();
    const daprClient = new DaprClient();
    const { mainSecretStore } = this.apiManagerConfigService;
    const apiMgrKeySecretName = this.apiManagerConfigService.apiMgrSecretName;
    const { mesPasswordSecretName } = this.apiManagerConfigService;
    const apiMgrKeyObject = await daprClient.secret.get(
      mainSecretStore,
      apiMgrKeySecretName,
    );
    const apiMgrKeyValue = Object.values(apiMgrKeyObject)[0];
    const mesPasswordObject = await daprClient.secret.get(
      mainSecretStore,
      mesPasswordSecretName,
    );
    const mesPasswordValue = Object.values(mesPasswordObject)[0];
    const queryParameters = new URLSearchParams();
    queryParameters.append('service', 'CombineQuery');
    queryParameters.append(
      'queryTemplate',
      'SC_MES_API/INTERFACE/EPARTBOARD/V1/INSERT_ACTION',
    );
    queryParameters.append('content-type', 'text/json');
    queryParameters.append('xacuteLoginName', mesUserName);
    queryParameters.append('xacuteLoginPassword', mesPasswordValue);
    queryParameters.append('session', 'false');

    queryParameters.append('InPlant', parameters.plant.toString());
    queryParameters.append('Param.1', parameters.actionType);
    queryParameters.append('Param.2', parameters.resource);
    queryParameters.append('Param.3', parameters.comment);
    queryParameters.append('Param.4', parameters.plant.toString());
    queryParameters.append('Param.5', parameters.startDateTime);
    queryParameters.append('Param.6', parameters.endDateTime);
    queryParameters.append('Param.7', parameters.writeDateTime);

    const plantLinkBaseUrl = await this.getPlantLink(parameters.plant);
    const isApiManagerEnabled =
      await this.apiManagerConfigService.apiManagerEnabled();

    const writeBackUrl = isApiManagerEnabled
      ? `${apiManagerUrl}/mii/illuminator/v1`
      : `${plantLinkBaseUrl}/XMII/Illuminator`;
    if (
      isApiManagerEnabled &&
      (!this.apiManagerConfigService.apiManager ||
        !this.apiManagerConfigService.mesUserName)
    ) {
      throw new Error('API Manager setup is incomplete');
    }
    try {
      const response = await firstValueFrom(
        this.customHttpService.post(
          writeBackUrl,
          queryParameters.toString(), // BODY
          {
            headers: {
              apiKey: apiMgrKeyValue,
            },
          },
        ),
      );
      const rowMessage =
        getMiiFirstMessage(response.data) ??
        getMiiCommandMessage(response.data);
      return {
        success: rowMessage === 'Command Query Successful',
      };
    } catch (error) {
      AppLogger.log(
        `Error in insertEDashboardAction: ${JSON.stringify(error)}`,
      );
      return undefined;
    }
  }

  /**
   * Update or create an SD comment for Event Center using the INSERT_ACTION transaction.
   * @param parameters The update payload.
   * @returns Success status.
   */
  public async updateEventCenterSdComment(
    parameters: UpdateEventCenterSdCommentDto,
  ): Promise<{ success: boolean }> {
    const toMiiDateTime = (value: string | undefined): string | undefined => {
      if (!value) {
        return undefined;
      }

      const alreadyFormatted = DateTime.fromFormat(
        value,
        'MM/dd/yyyy HH:mm:ss',
      );
      if (alreadyFormatted.isValid) {
        return value;
      }

      const parsedIso = DateTime.fromISO(value, { setZone: true });
      if (parsedIso.isValid) {
        return parsedIso.toFormat('MM/dd/yyyy HH:mm:ss');
      }

      return undefined;
    };

    const startDateTime = toMiiDateTime(parameters.startDateTime);
    const endDateTime = toMiiDateTime(parameters.endDateTime);
    const writeDateTime =
      toMiiDateTime(parameters.writeDateTime) ??
      DateTime.utc().toFormat('MM/dd/yyyy HH:mm:ss');

    if (!startDateTime || !endDateTime) {
      throw new BadRequestException(
        'Invalid startDateTime or endDateTime format. Use ISO or MM/dd/yyyy HH:mm:ss.',
      );
    }

    const writebackPayload: WriteBackActionDto = {
      actionType: 'HOUR_ACTION',
      comment: parameters.comment ?? '',
      endDateTime,
      plant: Number(parameters.plant),
      resource: parameters.resourceId,
      startDateTime,
      writeDateTime,
    };
    const result = await this.insertSlowDown(writebackPayload);
    return { success: result?.success === true };
  }

