  /**
   * Get hourly aggregation for a given query.
   * @param query The hourly aggregation query DTO.
   * @returns The hourly aggregated production data.
   */
  public async getHourlyAggregation(
    query: HourlyAggregationQueryDto,
  ): Promise<Array<HourlyAggregatedProductionDto>> {
    const { plant, resourceId, shiftStartDate, shiftEndDate, timezone } = query;
    // Normalize provided dates to UTC ISO using helper (handles naive + timezone)
    const shiftStartUtcIso = resolveToUtcIso(shiftStartDate, timezone);
    const shiftEndUtcIso = resolveToUtcIso(shiftEndDate, timezone);
    const { resourceApiAppId } = this.urlApiConfigService;
    const daprClient = new DaprClient();
    try {
      // Build query string for GET request
      const queryParameters = new URLSearchParams({
        plant: String(Number(plant)),
        resourceId,
        shiftEndDate: shiftEndUtcIso,
        shiftStartDate: shiftStartUtcIso,
      }).toString();
      const endpoint = `shift-tracking/hourly-aggregation?${queryParameters}`;
      // Invoke resource API app for hourly aggregation
      const results = (await daprClient.invoker.invoke(
        resourceApiAppId,
        endpoint,
        HttpMethod.GET,
        undefined,
        this.getInvokerOptions(),
      )) as Record<string, HourlyAggregatedProductionDto>;

      const typedResults: Array<HourlyAggregatedProductionDto> = Object.keys(
        results,
      )
        .filter((key) => !Number.isNaN(Number(key)))
        .sort((a, b) => Number(a) - Number(b))
        .map((key) => results[key]);

      // Fetch hourly comments for the given period
      const hourlyComments = await this.getHourlyComments(
        plant,
        resourceId,
        shiftStartUtcIso,
        shiftEndUtcIso,
      );

      // Fetch active cause tickets avec les dates du shift actuel
      // L'API retourne automatiquement les tickets actuels + anciens
      const {
        activeCauseTicketsMap,
        previousShiftTicketsCount,
        mostRecentTicket,
      } = await this.getActiveCauseTickets(
        plant,
        resourceId,
        timezone,
        shiftStartUtcIso,
        shiftEndUtcIso,
      );

      // Calcul de l'heure locale de début de shift pour la règle spéciale première heure
      const shiftStartLocalHour: number | undefined = (():
        | number
        | undefined => {
        try {
          const dt = DateTime.fromISO(shiftStartUtcIso, { zone: 'utc' });
          const dtLocal = timezone ? dt.setZone(timezone) : dt;
          return dtLocal.hour; // 0-23
        } catch {
          return undefined;
        }
      })();

      // Post-process results converting UTC-based fields to plant local timezone
      if (timezone && typedResults.length > 0) {
        const transformed = typedResults.map((item) => {
          const copy: HourlyAggregatedProductionDto = {
            ...item,
          } as HourlyAggregatedProductionDto;
          // Convert incoming UTC ISO strings to local plant time (naive, no offset, no Z)
          if (item.dateHourFrom) {
            const dtUtcFrom = DateTime.fromISO(String(item.dateHourFrom), {
              zone: 'utc',
            });
            if (dtUtcFrom.isValid) {
              const localFrom = dtUtcFrom.setZone(timezone);
              // Format: YYYY-MM-DDTHH:mm:SS.SSS (no offset, no Z)
              copy.dateHourFrom = localFrom.toFormat(
                "yyyy-MM-dd'T'HH:mm:ss.SSS",
              );
            }
          }
          if (item.dateHourTo) {
            const dtUtcTo = DateTime.fromISO(String(item.dateHourTo), {
              zone: 'utc',
            });
            if (dtUtcTo.isValid) {
              const localTo = dtUtcTo.setZone(timezone);
              copy.dateHourTo = localTo.toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS");
            }
          }
          if (item.hour !== undefined && item.hour !== null) {
            const parsedHour = Number(item.hour);
            if (!Number.isNaN(parsedHour)) {
              const localHour = convertUtcHourToPlantLocal(
                parsedHour,
                timezone,
              );
              if (localHour !== undefined) {
                copy.hour = localHour.toString().padStart(2, '0');
              }
            }

            const computeComments = (
              hour: string | number,
              slowdown: number,
              hourlyCommentsMap: Record<
                string,
                { comments: number; tickets: Array<TicketInfo> }
              >,
              description?: string,
            ): number => {
              const baseComments =
                hourlyCommentsMap[Number(hour)]?.comments ?? 0;
              const slowdownValue = Number(slowdown ?? 0);
              const hasDescription =
                typeof description === 'string' &&
                description.trim().length > 0;
              const slowdownTriggers =
                !hasDescription &&
                slowdownValue !== 0 &&
                Math.abs(slowdownValue) >= 5;
              return baseComments + (slowdownTriggers ? 1 : 0);
            };

            const getMostRecentTicketForHour = (
              hour: number,
              dateHourTo: string | undefined,
              mostRecentTickets: Array<{ ticket: string; startDate: DateTime }>,
            ): string | undefined => {
              if (mostRecentTickets.length === 0) return undefined;

              const isFirstHour =
                shiftStartLocalHour !== undefined &&
                hour === shiftStartLocalHour;

              let relevantTickets: Array<{
                ticket: string;
                startDate: DateTime;
              }> = [];

              if (isFirstHour && dateHourTo) {
                const dtLimit = DateTime.fromISO(dateHourTo, {
                  zone: timezone ?? 'utc',
                });
                relevantTickets = mostRecentTickets.filter((t) => {
                  const dtLocal = timezone
                    ? t.startDate.setZone(timezone)
                    : t.startDate;
                  return dtLocal <= dtLimit;
                });
              } else {
                relevantTickets = mostRecentTickets.filter((t) => {
                  const dtLocal = timezone
                    ? t.startDate.setZone(timezone)
                    : t.startDate;
                  return dtLocal.hour === hour;
                });
              }

              if (relevantTickets.length === 0) return undefined;

              relevantTickets.sort(
                (a, b) => b.startDate.toMillis() - a.startDate.toMillis(),
              );
              return relevantTickets[0].ticket;
            };
            copy.comments = computeComments(
              item.hour,
              item.slowdown,
              hourlyComments,
              item.description,
            );
            const hourKeyForTicketsRecent = Number(copy.hour ?? item.hour);
            copy.tickets = hourlyComments[Number(item.hour)]?.tickets ?? [];
            // Determine the most recent ticket for this hour
            copy.mostRecentTicket = getMostRecentTicketForHour(
              hourKeyForTicketsRecent,
              copy.dateHourTo,
              mostRecentTicket,
            );
            // UcTicket: nombre de tickets actifs cause 6 démarrés pendant cette heure locale
            // On utilise l'heure locale déjà convertie si possible, sinon l'heure UTC de base.
            const hourKeyForTickets = Number(copy.hour ?? item.hour);
            let ucTicketCount = activeCauseTicketsMap[hourKeyForTickets] ?? 0;
            // Cas spécial: première heure du shift → additionne tous les tickets du shift précédent
            if (
              shiftStartLocalHour !== undefined &&
              hourKeyForTickets === shiftStartLocalHour
            ) {
              ucTicketCount += previousShiftTicketsCount;
            }
            copy.ucTicket = ucTicketCount;
          }

          return copy;
        });

        return transformed;
      }

      return typedResults;
    } catch (error) {
      this.logger.error(
        'Error invoking resource API for hourly aggregation:',
        error,
      );
      throw error;
    }
  }

  /**
   * Get shift context for a given request.
   * @param request The shift context request DTO.
   * @returns The shift context result.
   */
  public async getShiftContext(
    request: GetShiftContextDto,
  ): Promise<ShiftContextResult> {
    // Parse date as UTC
    const { masterApiAppId } = this.urlApiConfigService;
    const daprClient = new DaprClient();
    try {
      const date = new Date(request.date);
      // Build query string for GET request
      const queryParameters = new URLSearchParams({
        date: date.toISOString(),
        plantId: request.plantId,
        workcenterId: request.workcenterId,
      }).toString();
      const endpoint = `shift-details/shift-context?${queryParameters}`;
      // Invoke master API app for shift context
      const result = await daprClient.invoker.invoke(
        masterApiAppId,
        endpoint,
        HttpMethod.GET,
        undefined,
        this.getInvokerOptions(),
      );
      const shiftResult = result as ShiftContextResult;
      const { timezone } = request;
      if (timezone) {
        const convertShift = (
          shift: ShiftContextResult['currentShift'],
        ): ShiftContextResult['currentShift'] => {
          if (!shift) return shift;
          const mutable = { ...shift };
          const start = DateTime.fromISO(mutable.startDatetime, {
            zone: 'utc',
          });
          const end = DateTime.fromISO(mutable.endDatetime, {
            zone: 'utc',
          });
          if (start.isValid) {
            mutable.startDatetime = start
              .setZone(timezone)
              .toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS");
          }
          if (end.isValid) {
            mutable.endDatetime = end
              .setZone(timezone)
              .toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS");
          }
          return mutable;
        };
        shiftResult.currentShift = convertShift(shiftResult.currentShift);
        shiftResult.previousShift = convertShift(shiftResult.previousShift);
        shiftResult.previousPreviousShift = convertShift(
          shiftResult.previousPreviousShift,
        );
      }

      return shiftResult;
    } catch (error) {
      this.logger.error('Error invoking master API for shift context:', error);
      throw error;
    }
  }

  private async getHourlyComments(
    plant: string,
    resourceId: string,
    from: string,
    to: string,
  ): Promise<Record<string, { comments: number; tickets: Array<TicketInfo> }>> {
    try {
      const { productionApiAppId } = this.urlApiConfigService;
      const daprClient = new DaprClient();

      const queryParameters = new URLSearchParams({
        from,
        plant: String(Number(plant)),
        resource: resourceId,
        to,
      }).toString();

      const endpoint = `down-time-ticket/hourly-comments?${queryParameters}`;

      const rawResponse = await daprClient.invoker.invoke(
        productionApiAppId,
        endpoint,
        HttpMethod.GET,
        undefined,
        this.getInvokerOptions(),
      );

      const typedResponse: HourlyCommentsResponseDto =
        rawResponse as HourlyCommentsResponseDto;

      const result: Record<
        string,
        { comments: number; tickets: Array<TicketInfo> }
      > = {};

      const hoursArray = Array.isArray(typedResponse?.hours)
        ? typedResponse.hours
        : [];

      for (const entry of hoursArray) {
        const hour = Number(entry.hour);
        if (!Number.isNaN(hour)) {
          result[hour] = {
            comments: entry.comments ?? 0,
            tickets: entry.tickets ?? [],
          };
        }
      }
      return result;
    } catch (error) {
      this.logger.error('Error fetching hourly comments via Dapr', error);
      return {};
    }
  }

  /**
   * Récupère les tickets de cause active avec filtrage par période du shift actuel.
   * L'API retourne automatiquement les tickets du shift actuel et les anciens tickets.
   * @param plant Identifiant numérique (string) de l'usine.
   * @param resourceId Identifiant de la ressource.
   * @param timezone Timezone IANA ou format UTC±H pour conversion locale.
   * @param startDate Date de début UTC ISO du shift actuel.
   * @param endDate Date de fin UTC ISO du shift actuel.
   * @returns Objet avec map heure locale -> count et count total des tickets anciens (previous shift).
   */
  private async getActiveCauseTickets(
    plant: string,
    resourceId: string,
    timezone: string | undefined,
    startDate: string,
    endDate: string,
  ): Promise<{
    activeCauseTicketsMap: Record<number, number>;
    previousShiftTicketsCount: number;
    mostRecentTicket: Array<{ startDate: DateTime; ticket: string }>;
  }> {
    const counts: Record<number, number> = {};
    let previousShiftCount = 0;
    const mostRecentTicket: Array<{ startDate: DateTime; ticket: string }> = [];

    try {
      const { productionApiAppId } = this.urlApiConfigService;
      const { plantHryApiAppId } = this.urlApiConfigService;
      const daprClient = new DaprClient();

      const resourceIsJIT = await daprClient.invoker.invoke(
        plantHryApiAppId,
        `resource/check-resource-type-JIT/${plant}/${resourceId}`,
        HttpMethod.GET,
        undefined,
        this.getInvokerOptions(),
      );

      const downtimeThreshold = (await daprClient.invoker.invoke(
        plantHryApiAppId,
        `plant/get-donwtime-threshold-by-plant/${plant}`,
        HttpMethod.GET,
        undefined,
        this.getInvokerOptions(),
      )) as DowntimeThresholdResponseDto;
      const threshold =
        downtimeThreshold.downtimeTicketReclassificationThreshold;
      const queryParameters = new URLSearchParams();
      let rawResponse;
      if (resourceIsJIT) {
        queryParameters.append('startDate', startDate);
        queryParameters.append('plant', String(Number(plant)));
        queryParameters.append('resource', resourceId);
        if (downtimeThreshold) {
          queryParameters.append('threshold', String(threshold));
        }

        rawResponse = await daprClient.invoker.invoke(
          productionApiAppId,
          `down-time-ticket/get-active-tickets-for-jit?${queryParameters.toString()}`,
          HttpMethod.GET,
          undefined,
          this.getInvokerOptions(),
        );
      } else {
        queryParameters.append('startDate', startDate);
        queryParameters.append('endDate', endDate);
        queryParameters.append('plant', String(Number(plant)));
        queryParameters.append('resource', resourceId);

        const endpoint = `down-time-ticket/get-active-cause-tickets?${queryParameters.toString()}`;

        rawResponse = await daprClient.invoker.invoke(
          productionApiAppId,
          endpoint,
          HttpMethod.GET,
          undefined,
          this.getInvokerOptions(),
        );
      }

      const tickets = Array.isArray(rawResponse) ? rawResponse : [];
      const currentShiftStartDt = DateTime.fromISO(startDate, {
        zone: 'utc',
      });

      // Refactor: process tickets in parallel to avoid await in loop
      await Promise.all(
        tickets.map(async (t) => {
          try {
            const startDateIso = t?.down_time_ticket_start_date;
            const ticketStartDt = DateTime.fromISO(startDateIso, {
              zone: 'utc',
            });

            if (ticketStartDt.isValid) {
              // Compter les tickets anciens (démarrés avant le shift actuel)
              if (ticketStartDt < currentShiftStartDt) {
                previousShiftCount += 1;
              }

              // Pour tous les tickets, calculer l'heure locale et incrémenter le compteur
              const dtLocal = timezone
                ? ticketStartDt.setZone(timezone)
                : ticketStartDt;
              const { hour } = dtLocal; // 0-23
              counts[hour] = (counts[hour] ?? 0) + 1;

              // Suivi du ticket le plus récent
              mostRecentTicket.push({
                startDate: ticketStartDt,
                ticket: t.down_time_ticket_ticket,
              });
            }
          } catch {
            // Ignore ticket parse errors individuellement
          }
        }),
      );
    } catch (error) {
      this.logger.error('Error fetching active cause tickets via Dapr', error);
    }

    return {
      activeCauseTicketsMap: counts,
      mostRecentTicket,
      previousShiftTicketsCount: previousShiftCount,
    };
  }

