  /**
   * Insert an eDashboard action for a plant and resource.
   * @param inPlant The plant number.
   * @param resourceId The resource ID.
   * @param actionType The action type.
   * @param comment The comment.
   * @param operatorCount The operatorCount.
   * @param startDateTime The start date and time.
   * @param endDateTime The end date and time.
   * @param target The target value (optional).
   * @returns The result of the action insertion.
   */
  public async insertEDashboardAction(
    inPlant: number,
    resourceId: string,
    actionType: string,
    comment: string,
    operatorCount: number,
    startDateTime: string,
    endDateTime: string,
    target?: number,
  ): Promise<{ message?: string; statusCode?: string; success: boolean }> {
    const apiManagerUrl = await this.apiManagerConfigService.apiManager();
    const mesUserName = await this.apiManagerConfigService.mesUserName();
    const daprClient = new DaprClient();
    const { mainSecretStore } = this.apiManagerConfigService;
    const apiMgrKeySecretName = this.apiManagerConfigService.apiMgrSecretName;
    const { mesPasswordSecretName } = this.apiManagerConfigService;
    const apiMgrKeyObject = await daprClient.secret.get(
      mainSecretStore,
      apiMgrKeySecretName,
    );
    const apiMgrKeyValue = Object.values(apiMgrKeyObject)[0];
    const mesPasswordObject = await daprClient.secret.get(
      mainSecretStore,
      mesPasswordSecretName,
    );
    const mesPasswordValue = Object.values(mesPasswordObject)[0];
    const parameters = new BalancingParamters({
      action: actionType,
      comment,
      contentType: 'text/json',
      dateFrom: startDateTime,
      dateTo: endDateTime,
      emptyFrom: '0',
      equipmentId: resourceId,
      inPlant,
      inUseShiftsEndDate: '0',
      opNumber: String(operatorCount),
      outputParameter: 'ResultXML',
      queryTemplate: 'SC_MES_API/INTERFACE/EPARTBOARD/V1/XCT_SAVE_MODEL',
      session: false,
      target: target === undefined ? '' : target.toString(),
      xacuteLoginName: `${mesUserName}`,
      xacuteLoginPassword: `${mesPasswordValue}`,
    });
    const plantLinkBaseUrl = await this.getPlantLink(inPlant);
    const isApiManagerEnabled =
      await this.apiManagerConfigService.apiManagerEnabled();

    const writeBackUrl = isApiManagerEnabled
      ? `${apiManagerUrl}/mii/illuminator/v1`
      : `${plantLinkBaseUrl}/XMII/Illuminator`;
    if (
      isApiManagerEnabled &&
      (!this.apiManagerConfigService.apiManager ||
        !this.apiManagerConfigService.mesUserName)
    ) {
      throw new Error('API Manager setup is incomplete');
    }
    try {
      const response = await firstValueFrom(
        this.customHttpService.post(writeBackUrl, undefined, {
          headers: {
            apiKey: apiMgrKeyValue,
          },
          maxBodyLength: Infinity,
          maxContentLength: Infinity,
          params: parameters,
        }),
      );
      const rowMessage = getMiiFirstMessage(response.data);
      const statusCode = getMiiFirstStatusCode(response.data);
      const success =
        statusCode?.toUpperCase() === 'SUCCESS' ||
        rowMessage === 'Command Query Successful';

      return {
        message: rowMessage,
        statusCode,
        success,
      };
    } catch (error) {
      AppLogger.log(
        `Error in insertEDashboardAction: ${JSON.stringify(error)}`,
      );
      return {
        message: 'Balancing writeback request failed',
        success: false,
      };
    }
  }
}

