}

import { DaprClient } from '@dapr/dapr';
import { Injectable } from '@nestjs/common';
import { HttpMethod } from 'dapr-client';
import { DateTime } from 'luxon';
import { EventCenterConfigurationHistoryItemDto } from './dtos/event-center-configuration-history-item.dto';
import { EventCenterConfigurationHistoryDto } from './dtos/event-center-configuration-history.dto';
import { EventCenterDowntimeItemDto } from './dtos/event-center-downtime-item.dto';
import { EventCenterHistoryHourDto } from './dtos/event-center-history-hour.dto';
import { EventCenterSdCommentDto } from './dtos/event-center-sd-comment.dto';
import { HourlyAggregatedProductionDto } from './dtos/hourly-aggregated-production.dto';
import { HourlyAggregationQueryDto } from './dtos/hourly-aggregation-query.dto';
import { ResourceConfigurationHistoryItemDto } from './dtos/resource-configuration-history-item.dto';
import { getAuthorizationHeaders } from './utils/epartboard.utils';
import {
  extractNumber,
  extractString,
  formatEventCenterDuration,
  getEventCenterHourKey,
} from './utils/event-center.helpers';
import { computeSdState, parseIsoInZone } from './utils/sd-comment.helpers';
import { AppLogger } from '@/common/logger/app-logger';
import { UrlApiConfigService } from '@/config/url-api/url-api.service';
import { resolveToUtcIso } from '@/helpers/timezone';

@Injectable()
export class EventCenterService {
  private static getInvokerOptions():
    | { headers: Record<string, string> }
    | undefined {
    const headers = getAuthorizationHeaders();
    return headers ? { headers } : undefined;
  }

  private static aggregateDowntimeByHour(
    rawGroups: Array<Record<string, unknown>>,
    zone: string,
    shiftEnd: DateTime,
  ): Map<string, Array<EventCenterDowntimeItemDto>> {
    const rowsByHour = new Map<string, Array<EventCenterDowntimeItemDto>>();

    for (const group of Array.isArray(rawGroups) ? rawGroups : []) {
      const tickets = Array.isArray(group.tickets) ? group.tickets : [];

      for (const rawTicket of tickets as Array<Record<string, unknown>>) {
        const itemData = EventCenterService.buildDowntimeItem(
          rawTicket,
          zone,
          shiftEnd,
        );

        if (itemData) {
          const hourKey = getEventCenterHourKey(itemData.startLocal);
          const items = rowsByHour.get(hourKey) ?? [];
          items.push(itemData.dto);
          rowsByHour.set(hourKey, items);
        }
      }
    }

    return rowsByHour;
  }

  private static buildDowntimeItem(
    rawTicket: Record<string, unknown>,
    zone: string,
    shiftEnd: DateTime,
  ): { dto: EventCenterDowntimeItemDto; startLocal: DateTime } | null {
    const startDate = extractString(rawTicket.startDate);

    if (!startDate) {
      return null;
    }

    const startUtc = DateTime.fromISO(startDate, { zone: 'utc' });

    if (!startUtc.isValid) {
      return null;
    }

    const startLocal = startUtc.setZone(zone);
    const endDate = extractString(rawTicket.endDate);
    const endLocal = endDate
      ? DateTime.fromISO(endDate, { zone: 'utc' }).setZone(zone)
      : shiftEnd;
    const duration = formatEventCenterDuration(startLocal, endLocal);

    const dto: EventCenterDowntimeItemDto = {
      cause: extractNumber(rawTicket.cause) ?? 0,
      cause1: extractString(rawTicket.cause1),
      cause2: extractString(rawTicket.cause2),
      causeDesc: extractString(rawTicket.causeDesc),
      causeDesc1: extractString(rawTicket.causeDesc1),
      causeDesc2: extractString(rawTicket.causeDesc2),
      dateHourFrom: startLocal.toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS"),
      dateHourTo: endLocal.toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS"),
      duration,
      endDate:
        endLocal === shiftEnd
          ? undefined
          : endLocal.toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS"),
      plant: extractNumber(rawTicket.plant) ?? 0,
      remark: extractString(rawTicket.remark),
      resource: extractString(rawTicket.resource) ?? '',
      shiftCode: extractNumber(rawTicket.shiftCode) ?? 0,
      startDate: startLocal.toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS"),
      status: extractString(rawTicket.status) ?? '',
      ticket: extractString(rawTicket.ticket) ?? '',
      time: startLocal.toFormat('HH:mm:ss'),
    };

    return { dto, startLocal };
  }

  private readonly logger = new AppLogger(EventCenterService.name);

  public constructor(
    private readonly urlApiConfigService: UrlApiConfigService,
  ) {}

  public async getEventCenterSdComments(
    query: HourlyAggregationQueryDto,
  ): Promise<Array<EventCenterSdCommentDto>> {
    const rows = await this.getEventCenterHourlyAggregationRows(query);
    const zone = query.timezone || 'utc';
    const parseIso = (value: string): DateTime => parseIsoInZone(value, zone);
    const buildSdCommentDto = (
      row: HourlyAggregatedProductionDto,
      hourStart: DateTime,
      hourEnd: DateTime,
    ): EventCenterSdCommentDto => {
      const slowdownValue = Number(row.slowdown ?? 0);
      const isEligible = slowdownValue !== 0 && Math.abs(slowdownValue) >= 5;
      const comment = row.description?.trim() ?? '';
      const isJustified = comment.length > 0;
      const state = computeSdState(isEligible, isJustified);
      const rowStart = parseIso(row.dateHourFrom);
      const rowEnd = row.dateHourTo ? parseIso(row.dateHourTo) : hourEnd;

      return {
        comment,
        dateHourFrom: (rowStart.isValid ? rowStart : hourStart).toFormat(
          "yyyy-MM-dd'T'HH:mm:ss.SSS",
        ),
        dateHourTo: (rowEnd.isValid ? rowEnd : hourEnd).toFormat(
          "yyyy-MM-dd'T'HH:mm:ss.SSS",
        ),
        hour: hourStart.toFormat('HH'),
        isEligible,
        isJustified,
        slowdown: Number.isNaN(slowdownValue) ? null : slowdownValue,
        state,
      };
    };
    const buildNoDataDto = (
      hourStart: DateTime,
      hourEnd: DateTime,
    ): EventCenterSdCommentDto => ({
      comment: '',
      dateHourFrom: hourStart.toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS"),
      dateHourTo: hourEnd.toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS"),
      hour: hourStart.toFormat('HH'),
      isEligible: false,
      isJustified: false,
      slowdown: null,
      state: 'NO_DATA',
    });

    const shiftStart = parseIso(query.shiftStartDate);
    const shiftEnd = parseIso(query.shiftEndDate);

    if (!shiftStart.isValid || !shiftEnd.isValid || shiftEnd <= shiftStart) {
      return [];
    }

    const rowsByHourStart = new Map<string, HourlyAggregatedProductionDto>();
    for (const row of rows) {
      if (row.dateHourFrom) {
        const rowStart = parseIso(row.dateHourFrom);
        if (rowStart.isValid) {
          rowsByHourStart.set(rowStart.startOf('hour').toISO() ?? '', row);
        }
      }
    }

    const output: Array<EventCenterSdCommentDto> = [];
    let cursor = shiftStart.startOf('hour');
    const shiftEndHour = shiftEnd.startOf('hour');

    while (cursor <= shiftEndHour) {
      const nextHour = cursor.plus({ hours: 1 });
      const row = rowsByHourStart.get(cursor.toISO() ?? '');
      output.push(
        row
          ? buildSdCommentDto(row, cursor, nextHour)
          : buildNoDataDto(cursor, nextHour),
      );
      cursor = nextHour;
    }

    return output;
  }

  public async getEventCenterConfigurationHistory(
    query: HourlyAggregationQueryDto,
  ): Promise<Array<EventCenterConfigurationHistoryDto>> {
    const { plant, resourceId, shiftStartDate, shiftEndDate, timezone } = query;
    const shiftStartUtcIso = resolveToUtcIso(shiftStartDate, timezone);
    const shiftEndUtcIso = resolveToUtcIso(shiftEndDate, timezone);
    const shiftStartUtc = DateTime.fromISO(shiftStartUtcIso, { zone: 'utc' });
    const shiftEndUtc = DateTime.fromISO(shiftEndUtcIso, { zone: 'utc' });
    const shiftStartUtcForResource = shiftStartUtc.isValid
      ? shiftStartUtc.toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS")
      : shiftStartUtcIso;
    const shiftEndUtcForResource = shiftEndUtc.isValid
      ? shiftEndUtc.toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS")
      : shiftEndUtcIso;
    const zone = timezone || 'utc';
    const parseIso = (value: string): DateTime => parseIsoInZone(value, zone);
    const shiftStart = parseIso(shiftStartDate);
    const shiftEnd = parseIso(shiftEndDate);

    if (!shiftStart.isValid || !shiftEnd.isValid || shiftEnd <= shiftStart) {
      return [];
    }

    const { resourceApiAppId } = this.urlApiConfigService;
    const daprClient = new DaprClient();
    const queryParameters = new URLSearchParams({
      plant: String(Number(plant)),
      resourceId,
      shiftEndDate: shiftEndUtcForResource,
      shiftStartDate: shiftStartUtcForResource,
    }).toString();

    const rows = (await daprClient.invoker.invoke(
      resourceApiAppId,
      `shift-tracking/configuration-history?${queryParameters}`,
      HttpMethod.GET,
      undefined,
      EventCenterService.getInvokerOptions(),
    )) as Array<ResourceConfigurationHistoryItemDto>;

    const localizedRows: Array<EventCenterConfigurationHistoryItemDto> =
      rows.map((row) => {
        const fromUtc = DateTime.fromISO(row.dateHourFrom, { zone: 'utc' });
        const toUtc = DateTime.fromISO(row.dateHourTo, { zone: 'utc' });
        const fromLocal = fromUtc.isValid ? fromUtc.setZone(zone) : fromUtc;
        const toLocal = toUtc.isValid ? toUtc.setZone(zone) : toUtc;

        return {
          action: row.action,
          dateHourFrom: fromLocal.toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS"),
          dateHourTo: toLocal.toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS"),
          duration: row.duration,
          fromAction: row.fromAction,
          time: fromLocal.toFormat('HH:mm:ss'),
        };
      });

    const rowsByHourStart = new Map<
      string,
      Array<EventCenterConfigurationHistoryItemDto>
    >();
    for (const row of localizedRows) {
      const rowStart = parseIso(row.dateHourFrom);
      if (rowStart.isValid) {
        const hourKey = getEventCenterHourKey(rowStart);
        const items = rowsByHourStart.get(hourKey) ?? [];
        items.push(row);
        rowsByHourStart.set(hourKey, items);
      }
    }

    const output: Array<EventCenterConfigurationHistoryDto> = [];
    let cursor = shiftStart.startOf('hour');
    const shiftEndHour = shiftEnd.startOf('hour');

    while (cursor <= shiftEndHour) {
      const nextHour = cursor.plus({ hours: 1 });
      output.push({
        dateHourFrom: cursor.toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS"),
        dateHourTo: nextHour
          .minus({ seconds: 1 })
          .toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS"),
        hour: cursor.toFormat('HH'),
        items: rowsByHourStart.get(getEventCenterHourKey(cursor)) ?? [],
      });
      cursor = nextHour;
    }

    return output;
  }

  public async getEventCenterHistory(
    query: HourlyAggregationQueryDto,
  ): Promise<Array<EventCenterHistoryHourDto>> {
    const zone = query.timezone || 'utc';
    const parseIso = (value: string): DateTime => parseIsoInZone(value, zone);
    const shiftStart = parseIso(query.shiftStartDate);
    const shiftEnd = parseIso(query.shiftEndDate);

    if (!shiftStart.isValid || !shiftEnd.isValid || shiftEnd <= shiftStart) {
      return [];
    }

    const [downtimeByHour, comments, configuration] = await Promise.all([
      this.getEventCenterDowntimeItemsByHour(query),
      this.getEventCenterSdComments(query),
      this.getEventCenterConfigurationHistory(query),
    ]);

    const commentsByHour = new Map<string, Array<EventCenterSdCommentDto>>();
    for (const row of comments) {
      // Exclude NO_DATA and NOT_ELIGIBLE placeholders
      if (row.state !== 'NO_DATA' && row.state !== 'NOT_ELIGIBLE') {
        const rowStart = parseIso(row.dateHourFrom);
        if (rowStart.isValid) {
          commentsByHour.set(getEventCenterHourKey(rowStart), [row]);
        }
      }
    }

    const configurationByHour = new Map<
      string,
      Array<EventCenterConfigurationHistoryItemDto>
    >();
    for (const row of configuration) {
      const rowStart = parseIso(row.dateHourFrom);
      if (rowStart.isValid) {
        configurationByHour.set(
          getEventCenterHourKey(rowStart),
          row.items ?? [],
        );
      }
    }

    const output: Array<EventCenterHistoryHourDto> = [];
    let cursor = shiftStart.startOf('hour');
    const shiftEndHour = shiftEnd.startOf('hour');

    while (cursor <= shiftEndHour) {
      const nextHour = cursor.plus({ hours: 1 });
      const hourKey = getEventCenterHourKey(cursor);

      output.push({
        comments: commentsByHour.get(hourKey) ?? [],
        configuration: configurationByHour.get(hourKey) ?? [],
        dateHourFrom: cursor.toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS"),
        dateHourTo: nextHour
          .minus({ seconds: 1 })
          .toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS"),
        downtime: downtimeByHour.get(hourKey) ?? [],
        hour: cursor.toFormat('HH'),
      });

      cursor = nextHour;
    }

    return output;
  }

  private async getEventCenterDowntimeItemsByHour(
    query: HourlyAggregationQueryDto,
  ): Promise<Map<string, Array<EventCenterDowntimeItemDto>>> {
    const { shiftStartDate, shiftEndDate, timezone } = query;
    const zone = timezone || 'utc';
    const parseIso = (value: string): DateTime => parseIsoInZone(value, zone);
    const shiftStart = parseIso(shiftStartDate);
    const shiftEnd = parseIso(shiftEndDate);

    if (!shiftStart.isValid || !shiftEnd.isValid || shiftEnd <= shiftStart) {
      return new Map<string, Array<EventCenterDowntimeItemDto>>();
    }

    const rawGroups = await this.fetchDowntimeHistory(query);
    return EventCenterService.aggregateDowntimeByHour(
      rawGroups,
      zone,
      shiftEnd,
    );
  }

  private async fetchDowntimeHistory(
    query: HourlyAggregationQueryDto,
  ): Promise<Array<Record<string, unknown>>> {
    const { plant, resourceId, shiftStartDate, shiftEndDate, timezone } = query;
    const shiftStartUtcIso = resolveToUtcIso(shiftStartDate, timezone);
    const shiftEndUtcIso = resolveToUtcIso(shiftEndDate, timezone);
    const { productionApiAppId } = this.urlApiConfigService;
    const daprClient = new DaprClient();
    const queryParameters = new URLSearchParams({
      plant: String(Number(plant)),
      resource: resourceId,
      shiftEnd: shiftEndUtcIso,
      shiftStart: shiftStartUtcIso,
    }).toString();

    return (await daprClient.invoker.invoke(
      productionApiAppId,
      `down-time-ticket/downtime-history?${queryParameters}`,
      HttpMethod.GET,
      undefined,
      EventCenterService.getInvokerOptions(),
    )) as Array<Record<string, unknown>>;
  }

  private async getEventCenterHourlyAggregationRows(
    query: HourlyAggregationQueryDto,
  ): Promise<Array<HourlyAggregatedProductionDto>> {
    const { plant, resourceId, shiftStartDate, shiftEndDate, timezone } = query;
    const shiftStartUtcIso = resolveToUtcIso(shiftStartDate, timezone);
    const shiftEndUtcIso = resolveToUtcIso(shiftEndDate, timezone);
    const { resourceApiAppId } = this.urlApiConfigService;
    const daprClient = new DaprClient();

    try {
      const queryParameters = new URLSearchParams({
        plant: String(Number(plant)),
        resourceId,
        shiftEndDate: shiftEndUtcIso,
        shiftStartDate: shiftStartUtcIso,
      }).toString();
      const endpoint = `shift-tracking/hourly-aggregation?${queryParameters}`;
      const results = (await daprClient.invoker.invoke(
        resourceApiAppId,
        endpoint,
        HttpMethod.GET,
        undefined,
        EventCenterService.getInvokerOptions(),
      )) as Record<string, HourlyAggregatedProductionDto>;

      const typedResults: Array<HourlyAggregatedProductionDto> = Object.keys(
        results,
      )
        .filter((key) => !Number.isNaN(Number(key)))
        .sort((a, b) => Number(a) - Number(b))
        .map((key) => results[key]);

      if (timezone && typedResults.length > 0) {
        return typedResults.map((item) => {
          const copy: HourlyAggregatedProductionDto = {
            ...item,
          } as HourlyAggregatedProductionDto;

          if (item.dateHourFrom) {
            const dtUtcFrom = DateTime.fromISO(String(item.dateHourFrom), {
              zone: 'utc',
            });
            if (dtUtcFrom.isValid) {
              const localFrom = dtUtcFrom.setZone(timezone);
              copy.dateHourFrom = localFrom.toFormat(
                "yyyy-MM-dd'T'HH:mm:ss.SSS",
              );
            }
          }
          if (item.dateHourTo) {
            const dtUtcTo = DateTime.fromISO(String(item.dateHourTo), {
              zone: 'utc',
            });
            if (dtUtcTo.isValid) {
              const localTo = dtUtcTo.setZone(timezone);
              copy.dateHourTo = localTo.toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS");
            }
          }

          return copy;
        });
      }

      return typedResults;
    } catch (error) {
      this.logger.error(
        'Error invoking resource API for Event Center hourly aggregation:',
        error,
      );
      return [];
    }
  }
}

import { BalancingMode } from '../dtos/configure-balancing.dto';

const authorizationHeader = 'Authorization';

/**
 * Get the authorization headers for API requests.
 * @returns The authorization headers if the token exists, otherwise undefined.
 */
export function getAuthorizationHeaders(): Record<string, string> | undefined {
  const token = process.env.TOKEN;

  return token ? { [authorizationHeader]: `Bearer ${token}` } : undefined;
}

/**
 * Get the model label based on the balancing mode.
 * @param mode The balancing mode.
 * @returns The model label string.
 */
export function getModelLabel(mode: BalancingMode): string {
  switch (mode) {
    case 'LOW': {
      return 'N-1';
    }
    case 'HIGH': {
      return 'N+1';
    }
    case 'SPECIAL': {
      return 'SPECIAL';
    }
    default: {
      return 'N';
    }
  }
}

import { DateTime } from 'luxon';

/**
 * Extracts a string value from an unknown type.
 * @param value The value to extract.
 * @returns String value or undefined if not a string.
 */
export function extractString(value: unknown): string | undefined {
  return typeof value === 'string' ? value : undefined;
}

/**
 * Extracts a number value from an unknown type.
 * @param value The value to extract.
 * @returns Number value or undefined if not a number.
 */
export function extractNumber(value: unknown): number | undefined {
  return typeof value === 'number' ? value : undefined;
}

/**
 * Converts a DateTime value to an event center hour key.
 * @param value DateTime value to convert.
 * @returns Event center hour key string in format "yyyy-MM-dd'T'HH".
 */
export function getEventCenterHourKey(value: DateTime): string {
  return value.startOf('hour').toFormat("yyyy-MM-dd'T'HH");
}

/**
 * Formats a duration between two datetimes as HH:mm:ss.
 * @param from Start datetime.
 * @param to End datetime.
 * @returns Duration string in HH:mm:ss format.
 */
export function formatEventCenterDuration(
  from: DateTime,
  to: DateTime,
): string {
  const totalSeconds = Math.max(
    0,
    Math.floor(to.toSeconds() - from.toSeconds()),
  );
  const hours = Math.floor(totalSeconds / 3600)
    .toString()
    .padStart(2, '0');
  const minutes = Math.floor((totalSeconds % 3600) / 60)
    .toString()
    .padStart(2, '0');
  const seconds = (totalSeconds % 60).toString().padStart(2, '0');

  return `${hours}:${minutes}:${seconds}`;
}

/**
 * Formats a duration given in minutes as HH:mm:ss.
 * @param minutes Duration in minutes.
 * @returns Duration string in HH:mm:ss format.
 */
export function formatDurationFromMinutes(minutes: number): string {
  const totalSeconds = Math.round(minutes * 60);
  const hours = Math.floor(totalSeconds / 3600)
    .toString()
    .padStart(2, '0');
  const mins = Math.floor((totalSeconds % 3600) / 60)
    .toString()
    .padStart(2, '0');
  const secs = (totalSeconds % 60).toString().padStart(2, '0');

  return `${hours}:${mins}:${secs}`;
}

const asRecord = (value: unknown): Record<string, unknown> | undefined => {
  return value && typeof value === 'object'
    ? (value as Record<string, unknown>)
    : undefined;
};

const asRecordArray = (
  value: unknown,
): Array<Record<string, unknown>> | undefined => {
  return Array.isArray(value)
    ? value
        .map((item) => asRecord(item))
        .filter((item): item is Record<string, unknown> => item !== undefined)
    : undefined;
};

const asString = (value: unknown): string | undefined => {
  return typeof value === 'string' ? value : undefined;
};

const getFirstRow = (
  responseData: unknown,
): Record<string, unknown> | undefined => {
  const root = asRecord(responseData);
  if (!root) {
    return undefined;
  }

  const rowsets = asRecord(root.Rowsets) ?? asRecord(root.rowsets);
  if (!rowsets) {
    return undefined;
  }

  const rowsetValue = rowsets.Rowset ?? rowsets.rowset;
  const rowsetArray = asRecordArray(rowsetValue);
  const firstRowset = rowsetArray?.[0] ?? asRecord(rowsetValue);
  if (!firstRowset) {
    return undefined;
  }

  const rowValue = firstRowset.Row ?? firstRowset.row;
  const rowArray = asRecordArray(rowValue);
  return rowArray?.[0] ?? asRecord(rowValue);
};

const extractMessage = (row: Record<string, unknown>): string | undefined => {
  const candidates = [
    row.STATUS_MESSAGE,
    row.status_message,
    row.statusMessage,
    row.statusmessage,
    row.message,
    row.Message,
    row.MESSAGE,
  ];

  for (const value of candidates) {
    const parsed = asString(value);
    if (parsed) {
      return parsed;
    }
  }

  return undefined;
};

const extractStatusCode = (
  row: Record<string, unknown>,
): string | undefined => {
  const candidates = [
    row.STATUS_CODE,
    row.status_code,
    row.statusCode,
    row.statuscode,
    row.code,
  ];

  for (const value of candidates) {
    const parsed = asString(value);

    if (parsed) {
      return parsed;
    }
  }

  return undefined;
};

/**
 * Extracts the first message from the MII response data.
 * @param responseData The response data object to extract the message from.
 * @returns The first message if found, otherwise undefined.
 */
export function getMiiFirstMessage(responseData: unknown): string | undefined {
  const firstRow = getFirstRow(responseData);
  return firstRow ? extractMessage(firstRow) : undefined;
}

/**
 * Extracts the first status code from the MII response data.
 * @param responseData The response data object to extract the status code from.
 * @returns The first status code if found, otherwise undefined.
 */
export function getMiiFirstStatusCode(
  responseData: unknown,
): string | undefined {
  const firstRow = getFirstRow(responseData);
  return firstRow ? extractStatusCode(firstRow) : undefined;
}

/**
 * Extracts the first message from MII responses that use the Messages array format.
 * Handles: { Rowsets: { Messages: [{ Message: "..." }] } }
 * Used by INSERT_ACTION (upsert/delete) transactions.
 * @param responseData The response data object.
 * @returns The message string if found, otherwise undefined.
 */
export function getMiiCommandMessage(
  responseData: unknown,
): string | undefined {
  const root = asRecord(responseData);
  const rowsets = asRecord(root?.Rowsets) ?? asRecord(root?.rowsets);
  const messages = asRecordArray(rowsets?.Messages ?? rowsets?.messages);
  const firstMessage = messages?.[0];
  if (!firstMessage) {
    return undefined;
  }
  return asString(firstMessage.Message ?? firstMessage.message);
}

import { DateTime } from 'luxon';
import { EventCenterSdCommentDto } from '../dtos/event-center-sd-comment.dto';

/**
 * Parse an ISO date string in the given IANA timezone, falling back to UTC.
 * @param value The ISO date string.
 * @param zone The IANA timezone string.
 * @returns A Luxon DateTime in the requested zone.
 */
export function parseIsoInZone(value: string, zone: string): DateTime {
  const withZone = DateTime.fromISO(value, { zone });
  if (withZone.isValid) {
    return withZone;
  }
  const asUtc = DateTime.fromISO(value, { zone: 'utc' });
  return asUtc.isValid
    ? asUtc.setZone(zone)
    : DateTime.invalid('invalid date time');
}

/**
 * Compute the SD comment state from eligibility and justification flags.
 * @param isEligible Whether the hour is eligible for a slowdown comment.
 * @param isJustified Whether the slowdown has been justified.
 * @returns The corresponding EventCenterSdCommentState value.
 */
export function computeSdState(
  isEligible: boolean,
  isJustified: boolean,
): EventCenterSdCommentDto['state'] {
  if (!isEligible) {
    return 'NOT_ELIGIBLE';
  }
  return isJustified ? 'JUSTIFIED' : 'TO_JUSTIFY';
}

import { AppLogger } from '@/common/logger/app-logger';
import { MleanTokenCache } from '@/redis/interfaces/mlean-token-cache.interface';
import { RedisService } from '@/redis/redis.service';

const logger = new AppLogger('MleanTokenHelper');

/**
 * Get mLean token from Redis cache.
 * Returns the token if found and not expired/expiring soon (within 10 minutes).
 * Returns undefined if token is not found, expired, or expiring soon.
 * @param redisService - RedisService instance
 * @param plant - Plant identifier
 * @returns Token string or undefined
 */
export async function getMLeanTokenFromCache(
  redisService: RedisService,
  plant: string,
): Promise<string | undefined> {
  const tokenData = await redisService.read(plant);
  const tenMinutesInMs = 10 * 60 * 1000;

  // If token not in cache or expired/expiring soon (within 10 minutes), return undefined
  if (!tokenData?.token || tokenData.exp * 1000 - Date.now() < tenMinutesInMs) {
    logger.warn(
      'Token not found or expired in cache, caller should fetch new token',
    );
    return undefined;
  }

  return tokenData.token;
}

/**
 * Ensure that a valid mLean token is cached in Redis.
 * If token is not in cache or expired/expiring soon (within 10 minutes),
 * fetches a new token and caches it.
 * @param redisService - RedisService instance
 * @param plantIdentifier - Plant identifier
 * @param getTokenFunction - Function to fetch a new token if needed
 */
export async function ensureTokenIsCached(
  redisService: RedisService,
  plantIdentifier: string,
  getTokenFunction: (plant: string) => Promise<MleanTokenCache | undefined>,
): Promise<void> {
  const tokenData = await redisService.read(plantIdentifier);
  const tenMinutesInMs = 10 * 60 * 1000;

  // If token not in cache or expired/expiring soon (within 10 minutes), fetch new token
  if (!tokenData?.token || tokenData.exp * 1000 - Date.now() < tenMinutesInMs) {
    const newToken = await getTokenFunction(plantIdentifier);
    if (newToken) {
      await redisService.write(plantIdentifier, newToken);
    }
  }
}

import { DateTime } from 'luxon';

/**
 * Converts an hour value expressed in UTC to the corresponding local hour in a plant timezone.
 * Mirrors the inverse logic of convertPlantLocalHourToUtc described elsewhere.
 *
 * Rules:
 * - If utcHour is undefined/null or out of [0,23], returns undefined.
 * - If timezone is falsy, returns the input hour (assumed already local / no conversion).
 * - Supports simplified textual timezones like "UTC+2", "GMT-5" (case-insensitive).
 * - Falls back to IANA timezone conversion using Luxon (DST-aware) when a valid IANA zone is provided.
 * @param utcHour Hour in UTC (0-23)
 * @param timezone Plant timezone string (e.g. 'UTC+2', 'Europe/Paris')
 * @param referenceDate Date used to anchor the conversion (default now) so DST can be resolved.
 * @returns Local hour (0-23) or undefined if invalid input/timezone.
 */
export function convertUtcHourToPlantLocal(
  utcHour: number | undefined,
  timezone: string | undefined,
  referenceDate: Date = new Date(),
): number | undefined {
  if (utcHour === undefined || utcHour === null) {
    return undefined;
  }
  if (utcHour < 0 || utcHour > 23) {
    return undefined;
  }
  if (!timezone) {
    return utcHour; // No timezone provided; treat as already local.
  }

  try {
    // Simple UTC/GMT±HH format (no minutes handling as per provided pattern)
    const simpleTzRegex = /^(?:utc|gmt)([+-]\d{1,2})$/i;
    const simpleMatch = simpleTzRegex.exec(timezone);
    if (simpleMatch) {
      const offset = Number(simpleMatch[1]); // E.g. +2, -5
      // Local = UTC + offset => compute local directly
      const local = (utcHour + offset + 24) % 24;
      return local;
    }

    // IANA timezone path (DST-aware)
    const dtUtc = DateTime.fromObject(
      {
        day: referenceDate.getUTCDate(),
        hour: utcHour,
        month: referenceDate.getUTCMonth() + 1,
        year: referenceDate.getUTCFullYear(),
      },
      { zone: 'utc' },
    );
    const dtLocal = dtUtc.setZone(timezone);
    if (!dtLocal.isValid) {
      return undefined;
    }
    return dtLocal.hour; // 0-23 local hour
  } catch {
    return undefined;
  }
}

/**
 * Converts a UTC Date object to a formatted date string in the plant's local timezone.
 * Returns a string in format: yyyy-MM-dd HH:mm:ss
 * @param utcDate The Date object in UTC to convert
 * @param timezone Plant timezone string (e.g. 'UTC+2', 'Europe/Paris')
 * @returns Formatted date string in plant timezone, or undefined if input is invalid
 */
export function formatUtcDateInPlantTimezone(
  utcDate: Date | undefined,
  timezone: string | undefined,
): string | undefined {
  if (!utcDate) {
    return undefined;
  }
  if (!timezone) {
    const dt = DateTime.fromJSDate(utcDate, { zone: 'utc' });
    return dt.toFormat('yyyy-MM-dd HH:mm:ss');
  }

  try {
    // Simple UTC/GMT±HH format
    const simpleTzRegex = /^(?:utc|gmt)([+-]\d{1,2})$/i;
    const simpleMatch = simpleTzRegex.exec(timezone);
    if (simpleMatch) {
      const offset = Number(simpleMatch[1]); // E.g. +2, -5
      const result = new Date(utcDate);
      result.setUTCHours(result.getUTCHours() + offset);
      const year = result.getUTCFullYear();
      const month = String(result.getUTCMonth() + 1).padStart(2, '0');
      const day = String(result.getUTCDate()).padStart(2, '0');
      const hours = String(result.getUTCHours()).padStart(2, '0');
      const minutes = String(result.getUTCMinutes()).padStart(2, '0');
      const seconds = String(result.getUTCSeconds()).padStart(2, '0');
      return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
    }

    // IANA timezone path (DST-aware) - format directly with Luxon
    const dtUtc = DateTime.fromJSDate(utcDate, { zone: 'utc' });
    const dtLocal = dtUtc.setZone(timezone);

    if (!dtLocal.isValid) {
      // Fallback to UTC formatting
      return dtUtc.toFormat('yyyy-MM-dd HH:mm:ss');
    }

    // Format directly from Luxon DateTime (preserves timezone)
    return dtLocal.toFormat('yyyy-MM-dd HH:mm:ss');
  } catch {
    // Fallback to UTC formatting
    const dt = DateTime.fromJSDate(utcDate, { zone: 'utc' });
    return dt.toFormat('yyyy-MM-dd HH:mm:ss');
  }
}

/**
 * @param originalDate Original date-time string.
 * @param timezone Optional timezone (IANA or simple UTC/GMT±HH) for naive interpretation.
 * @returns UTC ISO string (e.g. 2025-09-09T14:00:00.000Z)
 */
export function resolveToUtcIso(
  originalDate: string,
  timezone?: string,
): string {
  if (!originalDate) throw new TypeError('Missing date value');
  let raw = originalDate.trim();

  // Accept space separator by converting to ISO-like before attempting ISO parse
  if (/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}(\.\d{1,3})?$/.test(raw)) {
    raw = raw.replace(' ', 'T');
  }

  const offsetRegex = /(Z|[+-]\d{2}:?\d{2})$/;
  let dt: DateTime | undefined;

  // First attempt: direct ISO parse (with zone if provided and no explicit offset)
  dt = offsetRegex.test(raw)
    ? DateTime.fromISO(raw)
    : DateTime.fromISO(raw, { zone: timezone ?? 'utc' });

  // Fallbacks if ISO parse failed (common when original had space or missing milliseco{ zone: timezonends and above normalization insufficient)
  if (!dt.isValid) {
    const zone = timezone ?? 'utc';
    dt = DateTime.fromFormat(originalDate, 'yyyy-MM-dd HH:mm:ss.SSS', {
      zone,
    });
    if (!dt.isValid) {
      dt = DateTime.fromFormat(originalDate, 'yyyy-MM-dd HH:mm:ss', { zone });
    }
  }

  if (!dt.isValid) {
    throw new TypeError(`Invalid date format: ${originalDate}`);
  }

  const utcIso = dt.toUTC().toISO({ suppressMilliseconds: false });
  return utcIso ?? dt.toUTC().toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
}

const authorizationHeader = 'Authorization';

/**
 * Builds the authorization headers used for Dapr invocations.
 * @returns Authorization headers when a token is available, otherwise undefined.
 */
export function getAuthorizationHeaders(): Record<string, string> | undefined {
  const token = process.env.TOKEN;

  return token ? { [authorizationHeader]: `Bearer ${token}` } : undefined;
}

/**
 * Builds the optional invoker options payload expected by the Dapr client.
 * @returns Dapr invoker options with headers when a token is available, otherwise undefined.
 */
export function getInvokerOptions():
  | { headers: Record<string, string> }
  | undefined {
  const headers = getAuthorizationHeaders();

  return headers ? { headers } : undefined;
}

// IMPORTANT: tracing must be the very first import so OpenTelemetry can
import './tracing/tracing';
import { ValidationPipe } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import type { NestExpressApplication } from '@nestjs/platform-express';
import { SwaggerModule, DocumentBuilder } from '@nestjs/swagger';
import * as express from 'express';
import { AppModule } from '@/app.module';
import { UrlApiConfigService } from '@/config/url-api/url-api.service';
/**
 *
 */
async function bootstrap(): Promise<void> {
  const app = await NestFactory.create<NestExpressApplication>(AppModule, {
    rawBody: true,
  });

  app.use('/datadog-proxy', express.raw({ type: '*/*' }));

  // Parse both standard JSON and CloudEvents JSON
  app.use(express.json({ type: 'application/json' }));
  app.use(express.json({ type: 'application/cloudevents+json' }));
  // Global validation pipe
  app.useGlobalPipes(
    new ValidationPipe({
      forbidNonWhitelisted: true,
      transform: true,
      whitelist: true,
    }),
  );

  app.enableCors({
    // Include W3C Trace Context headers (traceparent, tracestate) so the
    // Datadog RUM Browser SDK can propagate trace IDs to the backend,
    // Also include the classic Datadog headers as a fallback.
    allowedHeaders: [
      'Content-Type',
      'Authorization',
      'traceparent',
      'tracestate',
      'x-datadog-trace-id',
      'x-datadog-parent-id',
      'x-datadog-origin',
      'x-datadog-sampling-priority',
    ].join(','),
    origin: '*',
  });

  const { urlApi } = app.get(UrlApiConfigService);

  const config = new DocumentBuilder()
    .setTitle('Backend Downtime Swagger Documentation')
    .setDescription(
      "In this page you'll find all of the necessary informations about the microservice Backend Downtime and it's different endpoints.",
    )
    .setVersion('1.0')
    .addServer(urlApi, 'pre-production')
    .build();

  const document = SwaggerModule.createDocument(app, config);
  SwaggerModule.setup('api', app, document);

  await app.listen(3000);
}

bootstrap();

export interface MleanTokenCache {
  token: string;
  exp: number;
  nbf: number;
  userId: number;
  scope: Array<string>;
  iss: string;
  lt: number;
}

import { Module } from '@nestjs/common';
import { ConfigModule } from '@nestjs/config';
import { DaprClient, DaprServer } from 'dapr-client';
import { DaprConfigModule } from '@/config/dapr/dapr-config.module';
import { RedisConfigModule } from '@/config/redis/redis-store.module';
import { RedisService } from '@/redis/redis.service';

@Module({
  exports: [RedisService],
  imports: [ConfigModule, RedisConfigModule, DaprConfigModule],
  providers: [
    { provide: DaprServer, useValue: new DaprServer() },
    DaprClient,
    RedisService,
  ],
})
export class RedisModule {}

import { Injectable } from '@nestjs/common';
import { DaprClient } from 'dapr-client';
import { MleanTokenCache } from './interfaces/mlean-token-cache.interface';
import { AppLogger } from '@/common/logger/app-logger';
import { RedisConfigService } from '@/config/redis/redis-store.service';

@Injectable()
export class RedisService {
  private readonly daprClient: DaprClient;

  private readonly customLogger: AppLogger = new AppLogger(RedisService.name);

  public constructor(private readonly redisConfigService: RedisConfigService) {
    this.daprClient = new DaprClient();
  }

  /**
   * Get the new Redis store name.
   * @returns An object containing:
   *   - `newStore`: the new Redis store name
   */ private getStores(): {
    newStore: string;
  } {
    return {
      newStore: this.redisConfigService.redisStoreAmr,
    };
  }

  public async read(plantKey: string): Promise<MleanTokenCache> {
    try {
      const { newStore } = this.getStores();

      const result = await this.daprClient.state.get(newStore, plantKey);

      let mleanTokenCacheResult: MleanTokenCache = {
        exp: 0,
        iss: '',
        lt: 0,
        nbf: 0,
        scope: [],
        token: '',
        userId: 0,
      };

      if (Object.values(result.valueOf()).length > 0) {
        // Attempt to parse the result if it's a string
        mleanTokenCacheResult =
          typeof result === 'string'
            ? (JSON.parse(result) as MleanTokenCache)
            : (result as MleanTokenCache);
      }
      return mleanTokenCacheResult;
    } catch (error) {
      this.customLogger.error(
        `Error reading from Redis with mutex for key ${plantKey}: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  /**
   * Write a key-value pair to AMR Redis.
   * @param plantKey - The key to write to Redis.
   * @param value - The value to associate with the key. Must conform to the MleanTokenCache interface.
   * @returns A Promise that resolves when the value has been successfully saved.
   * @throws Throws an error if the write operation fails.
   */
  public async write(plantKey: string, value: MleanTokenCache): Promise<void> {
    try {
      const { newStore } = this.getStores();

      if (newStore)
        await this.daprClient.state.save(newStore, [{ key: plantKey, value }]);
    } catch (error) {
      this.customLogger.error(
        `Redis write for plant ${plantKey} - Error writing to Redis with mutex: ${plantKey} ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }
}

