  }
}

/**
 * OpenTelemetry tracing initialization for Datadog RUM–Traces correlation.
 *
 * IMPORTANT: This file MUST be imported at the very top of main.ts,
 * before any NestJS or Express imports, so that HTTP patching takes effect.
 *
 * The W3CTraceContextPropagator reads the `traceparent` / `tracestate` headers
 * injected by the Datadog Browser RUM SDK and propagates the trace context
 * through every outgoing HTTP call, allowing end-to-end correlation between
 * browser sessions and backend spans in the Datadog APM UI.
 *
 * Ref: https://docs.datadoghq.com/opentelemetry/correlate/rum_and_traces/?tab=browserrum
 */

import { Logger } from '@nestjs/common';
import { W3CTraceContextPropagator } from '@opentelemetry/core';
import { OTLPTraceExporter as OTLPTraceExporterGrpc } from '@opentelemetry/exporter-trace-otlp-grpc';
import { OTLPTraceExporter } from '@opentelemetry/exporter-trace-otlp-http';
import { OTLPTraceExporter as OTLPTraceExporterProto } from '@opentelemetry/exporter-trace-otlp-proto';
import 'dotenv/config';
import { HttpInstrumentation } from '@opentelemetry/instrumentation-http';
import { resourceFromAttributes } from '@opentelemetry/resources';
import { NodeSDK } from '@opentelemetry/sdk-node';
import { TracingResourceAttributesDto } from './dto/tracing-resource-attributes.dto';

const logger = new Logger('Tracing');

const isEnabled = process.env.OTEL_ENABLED === 'true';

if (isEnabled) {
  try {
    /**
     * OTEL_EXPORTER_OTLP_PROTOCOL selects the transport to the collector:
     *   grpc         → port 4317  (OTLPTraceExporter from exporter-trace-otlp-grpc)
     *   http/protobuf → port 4318  (OTLPTraceExporter from exporter-trace-otlp-proto)
     *   http/json    → port 4318  (OTLPTraceExporter from exporter-trace-otlp-http)  ← default
     * OTEL_EXPORTER_OTLP_ENDPOINT overrides the address when the default doesn't fit.
     */
    const protocol = process.env.OTEL_EXPORTER_OTLP_PROTOCOL ?? 'http/json';

    const defaultEndpoint =
      protocol === 'grpc'
        ? 'http://localhost:4317'
        : 'http://localhost:4318/v1/traces';

    const exporterEndpoint =
      process.env.OTEL_EXPORTER_OTLP_ENDPOINT ?? defaultEndpoint;

    type SpanExporter =
      | OTLPTraceExporter
      | OTLPTraceExporterGrpc
      | OTLPTraceExporterProto;

    let exporter: SpanExporter;
    if (protocol === 'grpc') {
      exporter = new OTLPTraceExporterGrpc({ url: exporterEndpoint });
    } else if (protocol === 'http/protobuf') {
      exporter = new OTLPTraceExporterProto({ url: exporterEndpoint });
    } else {
      exporter = new OTLPTraceExporter({ url: exporterEndpoint });
    }

    const sdk = new NodeSDK({
      // Auto-instrument HTTP — this propagates traceparent/tracestate on
      // Outbound calls and reads them from inbound requests so every request
      // From the RUM SDK is linked to its backend span.
      instrumentations: [
        new HttpInstrumentation({
          ignoreIncomingRequestHook: (request): boolean => {
            // Skip OPTIONS (CORS preflight) and internal health routes
            if (request.method === 'OPTIONS') return true;
            const url = request.url ?? '';
            return ['/probes', '/dapr/subscribe', '/health'].some((pattern) =>
              url.includes(pattern),
            );
          },
        }),
      ],

      resource: resourceFromAttributes(
        new TracingResourceAttributesDto(
          process.env.DD_ENV ?? 'development',
          process.env.DD_SERVICE ?? 'epart-board-backend',
          process.env.npm_package_version ?? '0.0.0',
        ).toAttributes(),
      ),

      // W3C Trace Context propagator: reads `traceparent` / `tracestate` headers
      // Injected by the Datadog RUM Browser SDK (propagatorTypes: ["tracecontext"]).
      textMapPropagator: new W3CTraceContextPropagator(),

      // Export traces via OTLP HTTP (NodeSDK wraps this in a BatchSpanProcessor)
      traceExporter: exporter,
    });

    sdk.start();
    logger.log(
      `Tracing started — protocol: ${protocol}, endpoint: ${exporterEndpoint}`,
    );

    // Graceful shutdown: flush batched spans before the process exits
    process.on('SIGTERM', () => {
      sdk
        .shutdown()
        .then(() => logger.log('Tracing shut down.'))
        .catch((error: unknown) => logger.error('Shutdown error:', error));
    });
  } catch (error: unknown) {
    logger.error('Tracing initialization failed:', error);
  }
} else {
  logger.log(
    'Tracing is disabled (OTEL_ENABLED !== "true"). Skipping initialization.',
  );
}

